window.READER_DATA={"title": "Hadha Al Din", "slug": "hadha-al-din", "pages": [{"n": 1, "paras": ["بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "هَذَا الدِّين", "سَيِّد قُطْب", "دار الشروق"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0001.png"}, {"n": 2, "paras": ["فهرست المحتويات", "مقدمة ٥ المدخل ٩ الفصل الأول: مفهوم التنمية البشرية ١٣ الفصل الثاني: التنمية البشرية في الإسلام ٢٥ الفصل الثالث: مقومات التنمية البشرية ٤١ الفصل الرابع: معوقات التنمية البشرية ٥٧ الفصل الخامس: آليات تفعيل التنمية البشرية ٧٣ الخاتمة ٨٩ المصادر والمراجع ٩٣"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0002.png"}, {"n": 3, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0003.png"}, {"n": 4, "paras": ["الطبعة الرابعة عشرة", "١٤٢١ه - ٢٠٠١م الطبعة الخامسة عشرة", "١٤٢٢ه - ٢٠٠١م", "جميع حقوق الطبع محفوظة", "© دار الشروق أسسها محمد المعلم عام ١٩٦٨", "القاهرة: ٨ شارع سيبويه المصري - رابعة العدوية - مدينة نصر ص.ب: ٣٣ البانوراما - تليفون: ٤٠٢٣٣٩٩ فاكس: ٤٠٣٧٥٦٧ (٢٠٢) البريد الإلكتروني: email: dar@shorouk.com"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0004.png"}, {"n": 5, "paras": ["سَيّد قُطْب", "هٰذَا الدِّين", "دار الشروق"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0005.png"}, {"n": 6, "paras": ["المحتويات", "منهج للبشر ٥ منهج متفرد ١٧ منهج ميسر ٢٩ منهج مؤثر ٤٢ رصيد الفطرة ٥١ رصيد التجربة ٦٦ خطوط مستقرة ٧٩ وبعد ٩٦"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0006.png"}, {"n": 7, "paras": ["بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "مَنْهَجٌ لِلْبَشَرِ", "هناك حقيقة أولية عن طبيعة هذا الدين ، وطريقة عمله في حياة البشر.. حقيقة أولية بسيطة .. ولكنها مع بساطتها ، كثيرا ما تُنسى ، أو لا تدرك ابتداء . فينشأ عن نسيانها أو عدم إدراكها خطأ جسيم في النظر إلى هذا الدين : حقيقته الذاتية وواقعه التاريخي . حاضره ومستقبله كذلك !", "إن البعض ينتظر من هذا الدين مادام منزَّلاً من عند الله أن يعمل فى حياة البشر بطريقة سحرية خارقة غامضة الأسباب ! ودون أى اعتبار لطبيعة البشر ، ولطاقاتهم الفطرية ، ولواقعهم المادى ، في أية مرحلة من مراحل نموهم ، وفى أية بيئة من بيئاتهم .", "وحين لا يرون أنه يعمل بهذه الطريقة ، وحين يرون أن الطاقة البشرية المحدودة ، والواقع المادى للحياة الإنسانية ، يتفاعلان معه ، فيتأثران به في فترات تأثرا واضحا ، على حين أنهما في فترات أخرى يؤثران تأثيرا مضادا لاتجاهه ، فتقعد بالناس شهواتهم وأطماعهم ، وضعفهم ونقصهم ، دون تلبية هتاف هذا الدين ، أو الاتجاه معه فى طريقه ..", "حين يرون هذا فإنهم يصابون بخيبة أمل لم يكونوا يتوقعونها مادام"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0007.png"}, {"n": 8, "paras": ["هذا الدين منزلا من عند الله أو يصابون بخلخلة في ثقتهم بجدية المنهج الديني للحياة وواقعيته . أو يصابون بالشك في الدين إطلاقا ! وهذه السلسلة من الأخطاء تنشأ كلها من خطأ واحد أساسي : هو عدم إدراك هذا الدين وطريقته ، أو نسيان هذه الحقيقة الأولية البسيطة .", "إن هذا الدين منهج إلهي للحياة البشرية . يتم تحقيقه في حياة البشر بجهد البشر أنفسهم في حدود طاقتهم البشرية ؛ وفى حدود الواقع المادي للحياة الإنسانية في كل بيئة ، ويبدأ العمل من النقطة التي يكون البشر عندها حينما يتسلم مقاليدهم . ويسير بهم إلى نهاية الطريق في حدود طاقتهم البشرية ، وبقدر ما يبذلونه من هذه الطاقة .", "وميزته الأساسية : أنه لا يغفل لحظة ، في أية خطة وفى أية خطوة عن فطرة الإنسان وحدود طاقته ، وواقع حياته المادي أيضا . وأنه في الوقت ذاته يبلغ به كما تحقق ذلك فعلا في بعض الفترات ، وكما يمكن أن يتحقق دائما كلما بذلت محاولة جادة إلى ما لم يبلغه أى منهج آخر من صنع البشر على الإطلاق . وفى يسر وراحة وطمأنينة واعتدال .", "ولكن الخطأ كله كما تقدم ينشأ من عدم إدراك طبيعة هذا الدين أو من نسيانها . ومن انتظار الخوارق المجهولة الأسباب على يديه ... تلك الخوارق التى تبدل فطرة الإنسان ، ولا تبالي طاقاته المحدودة ، ولا تحفل واقعه المادي البيئي !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0008.png"}, {"n": 9, "paras": ["أليس هو من عند الله ؟ أليس الله قادراً على كل شئ ؟ فلماذا إذن يعمل هذا الدين فقط في حدود الطاقة البشرية المحدودة ؟ وتتأثر نتائج عمله بالضعف البشري ؟ بل لماذا يحتاج أصلا إلى الجهد البشري ؟ ثم .. لماذا لا ينتصر دائماً ، ولا ينتصر أصحابه دائماً ؟ لماذا تغلب ثقلة الضعف والشهوات والواقع المادى على رفرفته وشفافيته وانطلاقه أحياناً ؟ ولماذا يغلب أهل الباطل على أصحابه وهم أهل الحق أحياناً ! ! وكلها كما ترى أسئلة وشبهات ، تنبع ابتداء من عدم إدراك الحقيقة الأولية لطبيعة هذا الدين وطريقته .. أو من نسيانها !", "إن الله قادر طبعا على تبديل فطرة الإنسان ، عن طريق هذا الدين أو عن غير طريقه . ولكنه سبحانه شاء أن يخلق الإنسان بهذه الفطرة لحكمة يعلمها . وشاء أن يجعل الهدى ثمرة للجهد والرغبة في الهدى : « والذين جاهدوا فينا لنهدينهم سبلنا » .. وشاء أن تعمل فطرة الإنسان دائماً ، ولا تمحى ولا تعطل : « ونفس وما سواها . فألهمها فجورها وتقواها . قد أفلح من زكاها . وقد خاب من دساها » .. وشاء أن يتم تحقيق منهجه الإلهى للحياة البشرية عن طريق الجهد البشري ، وفى حدود الطاقة البشرية : « إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم » .. « ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض » . وشاء أن يبلغ الإنسان من هذا كله بقدر ما يبذل من الجهد ، وما ينفق من الطاقة ، وما يصبر على الابتلاء في تحقيق هذا المنهج الإلهي القويم ، وفى دفع الفساد عن نفسه وعن الحياة من حوله : « أحسب الناس أن"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0009.png"}, {"n": 10, "paras": ["يتركوا أن يقولوا آمنا وهم لا يفتنون . ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكاذبين » :.", "وليس لأحد من خلق الله أن يسأله سبحانه لماذا شاء هذا كله على هذا النحو الذى أراده فكان . ليس لأحد من خلقه أن يسأله سبحانه مادام أن أحدا من خلقه ليس إلها ، وليس لديه العلم ولا إمكان العلم بالنظام الكلى لهذا الكون ؛ ومقتضيات هذا النظام في طبيعة كل كائن فى هذا الوجود .", "ولماذا ؟ فى هذا المقام سؤال لا يسأله مؤمن جاد ، ولا يسأله ملحد جاد .. المؤمن لا يسأله ، لأنه أكثر أدبا مع الله الذى يعرفه بذاته وصفاته وخصائصه وأكثر معرفة بطبيعة إدراكه البشرى وحدوده ، وأنه لم يهيأ للعمل فى هذا المجال .. والملحد الجاد لا يسأله ، لأنه لا يعترف بالله ابتداء ، فإن هو اعترف بألوهيته عرف معها أن هذا شأنه سبحانه ومقتضى ألوهيته ، وأنه : « لا يسأل عما يفعل وهم يسألون » . لأنه وحده المهيمن العليم بما يفعل .", "ولكنه سؤال قد يسأله هازل مائع . لا هو مؤمن جاد ، ولا هو ملحد جاد . ومن ثم لا يجوز الاحتفال به ، ولا أخذه مأخذ الجد .. وقد يسأله جاهل بحقيقة الألوهية وخصائصها . فالسبيل لتعليم هذا الجاهل ليس هو الإجابة المباشرة . إنما هو تعريفه بحقيقة الألوهية وخصائصها .. حتى يعرفها ويسلم بها فهو مؤمن . أو يجحدها وينكرها فهو ملحد .. وبهذا ينتهى الجدل . إلا أن يكون مراء ! والمسلم منهى عن المضى فى الجدل حتى يكون مراء !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0010.png"}, {"n": 11, "paras": ["والخلاصة التى ننتهى إليها من هذا الاستطراد فى هذه الفقرة : هى أنه ليس لأحد من خلق الله أن يسأله سبحانه لماذا شاء أن يخلق «الإنسان» بهذه الفطرة ؟ ولماذا شاء أن يبقى فطرته هذه عاملة لا تمحى ولا تعطل ؟ ولماذا شاء أن يجعل المنهج الإلهى لحياته البشرية يتحقق عن طريق الجهد البشرى ، وفى حدود الطاقة البشرية ، والواقع المادى لحياته ؟ ولم يشأ أن يجعله يتم بوسيلة خارقة ، وبأسباب مبهمة غامضة !", "ولكن لكل أحد من خلقه أن يدرك هذه الحقائق ويعرفها ؛ ويراها وهى تعمل فى واقع الحياة البشرية . ويفسر أحداث التاريخ البشرى على ضوئها . فيفقه خط سيرها التاريخى من ناحية ؛ ويعرف كيف يواجه هذا الخط ويوجهه من ناحية أخرى . ويعيش مع حكمة الله وقدره ، فينطبع بهما الانطباع الصحيح من ناحية ثالثة .", "هذا المنهج الإلهى ، الذى يمثله «الإسلام» فى صورته النهائية ، كما جاء بها محمد صلى الله عليه وسلم ، لا يتحقق فى الأرض ، وفى دنيا الناس ، بمجرد تنزله من عند الله . لا يتحقق بكلمة : «كن» الإلهية ، مباشرة لحظة تنزله . ولا يتحقق بمجرد إبلاغه للناس وبيانه . ولا يتحقق بالقهر الإلهى على نحو ما يمضى ناموسه فى دورة الفلك وسير الكواكب . إنما يتحقق بأن تحمله جماعة من البشر . تؤمن به إيمانا كاملا ، وتستقيم عليه بقدر طاقتها وتجتهد لتحقيقه فى قلوب الآخرين وفى حياتهم كذلك ؛ وتجاهد لهذه الغاية بكل ما تملك .. تجاهد الضعف البشرى"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0011.png"}, {"n": 12, "paras": ["والهوى البشرى فى داخل النفوس . وتجاهد الذين يدفعهم الضعف والهوى للوقوف فى وجه الهدى .. وتبلغ بعد ذلك كله من تحقيق هذا المنهج ، إلى الحد الذى تطيقه فطرة البشر ، والذى يهيئه لهم واقعهم المادى . على أن تبدأ بالبشر من النقطة التى هم فيها فعلا ؛ ولا تغفل واقعهم ، ومقتضياته فى سير وتتابع مراحل هذا المنهج الإلهى .. ثم تنتصر هذه الجماعة على نفسها وعلى نفوس الناس معها تارة . وتنهزم فى المعركة مع نفسها أو مع نفوس الناس تارة .. بقدر ما تبذل من الجهد . وبقدر ما تتخذ من الوسائل المناسبة للزمان ولمقتضيات الأحوال . وقبل كل شىء .. بمقدار ما تمثل هى ذاتها من حقيقة هذا المنهج ؛ ومن ترجمته ترجمة عملية فى واقعها وسلوكها الذاتى .", "هذه هى طبيعة هذا الدين وطريقته . وهذه هى خطته الحركية ووسيلته .. وهذه هى الحقيقة التى شاء الله أن يعلمها للجماعة المسلمة وهو يقول لها : « إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم » . « ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض » . « والذين جاهدوا فينا لنهدينهم سبلنا » .", "وهذه هى الحقيقة التى شاء الله أن يعلمها للجماعة المسلمة فى غزوة أحد حينما قصرت فى تمثيل حقيقة هذا الدين فى ذوات أنفسها فى بعض مواقف الغزوة . وحينما قصرت فى اتخاذ الوسائل المناسبة فى بعض مواقفها . وحينما غفلت عن هذه الحقيقة الأولية أو نسيتها ؛ وفهمت أن من مقتضى"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0012.png"}, {"n": 13, "paras": ["كونها مسلمة أن تنتصر حتما ! فقال لها الله سبحانه : « أو لما أصابتكم مصيبة قد أصبتم مثليها قلتم : أنى هذا ؟ قل : هو من عند أنفسكم » . وقال لها . « ولقد صدقكم الله وعده إذ تحسونهم بإذنه ، حتى إذا فشلتم وتنازعتم فى الأمر ، وعصيتم من بعد ما أراكم ما تحبون : منكم من يريد الدنيا ومنكم من يريد الآخرة . ثم صرفكم عنهم ليبتليكم » .", "ولقد تعلمت الجماعة المسلمة هذه الحقيقة فى هذه الغزوة ، لا بالكلام ولا بالعتاب ؛ ولكن تعلمتها مع هذا بالدماء وبالآلام . ودفعت ثمنها غاليا : هزيمة بعد نصر . وخسارة بعد غنم . وجراحا لم تكد تدع أحدا معافى . وشهداء كراما فيهم سيد الشهداء حمزة رضى الله عنه وأغلى من ذلك كله وأشد وقعا على الجماعة المسلمة كلها : جرح رسول الله صلى الله عليه وسلم ، وشج وجهه الكريم ، وكسر رباعيته فى فمه ، ووقوعه لجنبه فى الحفر التى حفرها أبو عمرو الفاسق حليف قريش مكيدة للمسلمين ؛ وجهد المشركين له صلى الله عليه وسلم وهم يطاردونه ، وهو مفرد فى نفر من أصحابه استشهدوا واحدا بعد واحد وهم يذودون عنه ؛ ويترس أحدهم أبو دجانة بظهره عليه يقيه نبل المشركين ، والنبل يقع فى ظهره فلا يتحرك .. حتى ثاب إليه المؤمنون من هزيمتهم وحيرتهم ، وهم يتلقون هذا الدرس الشاق المرير !", "على أنه من الملاحظ الواضح أن ترك المنهج الإلهى للجهد البشرى ، يتولى تحقيقه فى حدود الطاقة البشرية ، يصلح النفوس البشرية ، ويصلح الحياة البشرية .. نقول هذا لا لنعلل به مشيئة الله سبحانه"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0013.png"}, {"n": 14, "paras": ["في جعل الأمر على ما جعله . ولكن لنسجل فقط ملاحظة واقعية لآثار هذه المشيئة فى حياة العباد .", "ذلك أن حقيقة الإيمان لا يتم تمامها فى قلب حتى يتعرض لمجاهدة الناس في أمر هذا الإيمان . مجاهدتهم بالقلب بكراهة باطلهم وجاهليتهم والعزم على نقلهم منها إلى الحق والإسلام . ومجاهدتهم باللسان بالتبليغ والبيان ، ورفض باطلهم الزائف ، وتقرير الحق الذي جاء به الإسلام . ومجاهدتهم باليد بالدفع والإزالة من طريق الهدى حين يعترضونه بالقوة الباغية والبطش الغشوم ! .. وحتى يتعرض في تلك المجاهدة للابتلاء والأذى ، والصبر على الابتلاء والأذى ، والصبر على الهزيمة والصبر على النصر أيضا فالصبر على النصر أشق من الصبر على الهزيمة . ثم يثبت ولا يرتاب ؛ ويستقيم ولا يتلفت ؛ ويمضى في طريق الإيمان راشدا صاعدا .", "حقيقة الإيمان لا يتم تمامها في قلب حتى يتعرض لمجاهدة الناس في أمر هذا الإيمان لأنه يجاهد نفسه كذلك فى أثناء مجاهدته للناس ؛ وتتفتح له فى الإيمان آفاق لم تكن لتتفتح له أبدا وهو قاعد آمن ساكن ، وتتبين له حقائق فى الناس وفى الحياة لم تكن لتتبين له أبدا بغير هذه الوسيلة . ويبلغ هو بنفسه وبمشاعره وتصوراته ، وبعاداته وطباعه وانفعالاته واستجاباته ، ما لم يكن ليبلغه أبدا بدون هذه التجربة الشاقة العسيرة .", "وهذا بعض ما يشير إليه قوله تعالى : «ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض» . وأول ما تفسد : فساد النفوس بالركود الذي تأسن معه الروح ؛ وتسترخى معه الهمة ، ويتلفها الرخاء والطراوة . ثم تأسن الحياة كلها بالركود . أو بالحركة في مجال الشهوات وحدها . كما يقع"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0014.png"}, {"n": 15, "paras": ["للأمم حين تبتلى بالرخاء !", "فهذه كذلك من الفطرة التى فطر الله الناس عليها . لقد جعل صلاح هذه الفطرة فى المجاهدة لإقرار منهج الله للحياة البشرية ، عن طريق الجهد البشرى ، وفى حدود الطاقة البشرية كذلك .", "ثم إن هذه المجاهدة وما يصاحبها من الابتلاء ، هى الوسيلة العملية لتمحيص الصفوف بعد تمحيص النفوس ولتنقية الجماعة من المعطلين والمعوقين والمرجفين ؛ ومن ضعاف النفوس والقلوب ، ومن المخادعين والمنافقين والمرائين ..", "وهذه هى الحقيقة التى شاء الله أن يعلمها للجماعة المسلمة وهى تتعرض للامتحان ؛ وتتعرض للابتلاء ؛ وتتكشف فيها خفايا النفوس ؛ كما تتميز فيها الصفوف . تحت مطارق الابتلاء ومشقة التجربة ، ومرارة الآلام .", "وهذه هى الحقيقة التى شاء الله أن يعلمها للجماعة المسلمة ، وهو يعقب على أحداث الغزوة . فيقول لها ، ردا على سؤال المسلمين : «أنى هذا ؟» «قل : هو من عند أنفسكم» .. ثم يعقب على هذا بقوله : «وما أصابكم يوم التقى الجمعان فبإذن الله . وليعلم المؤمنين وليعلم الذين نافقوا» .. «وما كان الله ليذر المؤمنين على ما أنتم عليه حتى يميز الخبيث من الطيب» .. «وليعلم الله الذين آمنوا ويتخذ منكم شهداء والله لا يحب الظالمين ، وليمحص الله الذين آمنوا ويمحق الكافرين» ... كل ذلك ليستقر فى حسهم أنه مع أن ما أصابهم كان بسبب تقصيرهم فى تمثيل"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0015.png"}, {"n": 16, "paras": ["حقيقة الإيمان كاملة في مشاعرهم وتصرفاتهم في الغزوة .. فإنه كذلك كان لخيرهم في النهاية بفضل الله عليهم ، وتجاوزه عن تقصيرهم ؛ واتخاذ نتائجه مادة لتعليمهم وتمحيصهم وتطهيرهم ، وتميز صفوفهم .. وكله خير لأنفسهم ولحياتهم في نهاية المطاف ..", "ولا يتم تمام القول في طبيعة هذا الدين وطريقته ، حتى نضيف إلى تلك الحقيقة التي نرجو أن نكون قد كشفنا عنها في هذا البيان .. تكملة ضرورية لها لابد من بيانها كذلك :", "إن كون هذا المنهج الإلهي متروك تحقيقه للجهد البشري ، في حدود الطاقة البشرية ، وفى حدود الواقع المادى للحياة الإنسانية في شتى المدارج ، وشتى البيئات .. لا يعنى استقلال الإنسان نهائيا بهذا الأمر ؛ وانقطاعه عن قدر الله وتدبيره ، ومدده وعونه وتوفيقه وتيسيره .. فتصور الأمر على هذا النحو مخالف في أصوله لطبيعة التصور الإسلامي .", "ولقد بينا فيما سلف أن الله سبحانه يساعد من يجاهد للهدى : «والذين جاهدوا فينا لنهدينهم سبلنا» .. وأنه يغير حال الناس حين يغيرون ما بأنفسهم ، وأنه لا يغير ما بهم حتى يغيروا ما بأنفسهم : «إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم» .", "وهذان النصان يوضحان لنا العلاقة بين الجهد البشري الذي يبذله الناس ، وعون الله ومدده الذي يسعفهم به ؛ فيبلغون به ما يجاهدون فيه من الخير والهدى والصلاح والفلاح .", "فإرادة الله هي الفاعلة في النهاية ؛ وبدونها لا يبلغ «الإنسان» بذاته"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0016.png"}, {"n": 17, "paras": ["شيئاً ، ولكن هذه الإرادة تعين من يعرف طريقها ، ويستمد عونها ويجاهد في الله ليبلغ رضاه .", "وقدر الله مع ذلك كله هو الذي يحيط بالناس والأحداث ؛ وهو الذي يتم وفقه ما يتم من ابتلاء ؛ ومن خير يصيبه الناجحون في هذا الابتلاء .", "وهذه هي الحقيقة التي شاء الله سبحانه أن يعلمها للجماعة المسلمة . وهو يبين لها في التعقيب على غزوة أحد أسباب النصر وأسباب الهزيمة من عملها ثم يكشف لها عن حكمة الله من وراء الابتلاء كله ، ومن وراء النصر والهزيمة ؛ وعن تدبيره كذلك « ولقد صَدَقكم الله وعده إذ تحسونهم بإذنه . حتى إذا فشلتم وتنازعتم في الأمر ، وعصيتم من بعد ما أراكم ما تحبون : منكم من يريد الدنيا ومنكم من يريد الآخرة . ثم صرفكم عنهم ليبتليكم » . وليعرفهم سنته الشاملة . ومردها في النهاية إلى مشيئته الطليقة وقدره النافذ من وراء الأسباب والوقائع : « إن يمسسكم قرح فقد مس القوم قرح مثله . وتلك الأيام نداولها بين الناس . وليعلم الله الذين آمنوا ، ويتخذ منكم شهداء . والله لا يحب الظالمين . وليمحص الله الذين آمنوا ويمحق الكافرين » .", "وإذن فهو في النهاية تدبير الله ومشيئته وقدره ، ليتم ما يريده من وراء الأسباب والأحداث ، وهو الأمر الذي لا يسأل عنه سبحانه : لأنه شأنه الإلهي ، الذي لا يسأل عنه .. وهذه هي حقيقة الإيمان الكبرى التي لا يتم في النفس إلا باستقرارها فيها ، واطمئنانها إليها .. وهى التكملة التي لابد منها لما قررناه في هذا الفصل عن طبيعة هذا الدين"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0017.png"}, {"n": 18, "paras": ["وطريقته .. بلا تعارض بين طرفي هذه الحقيقة في حس المسلم ، الذى يتذوق قلبه حقيقة هذا الدين ، كما أنزلها الله . ولا يعارضها بتصورات ومقررات ليست مستقاة من كتاب الله .."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0018.png"}, {"n": 19, "paras": ["مَنْهَجٌ مُتَفَرِّد", "والآن يقول قائل : إذا كان الإسلام ، وهو منهج الله للحياة البشرية ، لا يتحقق في الأرض وفى دنيا الناس ، إلا بالجهد البشرى ، وفى حدود الطاقة البشرية ، وفى حدود الواقع المادى للحياة الإنسانية فى البيئات المختلفة .. فما ميزته إذن على المناهج البشرية ، التي يضعها البشر لأنفسهم ، ويبلغون منها ما يبلغه جهدهم ، فى حدود طاقتهم وواقعهم ؟ ولماذا يجب أن نحاول تحقيق ذلك المنهج ، وهو يحتاج إلى الجهد البشرى ككل منهج ؟ فلا يتحقق منه شئ بمعجزة خارقة ، ولا بقهر إلهي ملزم ؟ وهو يتحقق فى حياة الناس ، فى حدود فطرتهم البشرية ، وطاقتهم العادية ، وأحوالهم الواقعية ؟!", "ونحن ملزمون بمحاولة تحقيق ذلك المنهج ابتداء لنحقق لأنفسنا صفة الإسلام . فركن الإسلام الأول : أن نشهد أن لا إله إلا الله وأن محمدا رسول الله .. وشهادة أن لا إله إلا الله ، معناها القريب : إفراد الله سبحانه بالألوهية ، وعدم إشراك أحد من خلقه معه فى خاصية واحدة من خصائصها .. وأولى خصائص الألوهية : حق الحاكمية المطلقة ، الذى ينشأ عنه حق التشريع للعباد ؛ وحق وضع المناهج لحياتهم ؛"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0019.png"}, {"n": 20, "paras": ["وحق وضع القيم التي تقوم عليها هذه الحياة . فشهادة «أن لا إله إلا الله» لا تقوم ولا تتحقق إلا بالاعتراف بأن لله وحده حق وضع المنهج الذي تجرى عليه الحياة البشرية ؛ وإلا بمحاولة تحقيق ذلك المنهج في حياة البشر ، دون سواه .. وكل من ادعى لنفسه حق وضع منهج لحياة جماعة من الناس ، فقد ادعى حق الألوهية عليهم ، بادعائه أكبر خصائص الألوهية . وكل من أقره منهم على هذا الادعاء فقد اتخذه إلها من دون الله ، بالاعتراف له بأكبر خصائص الألوهية .. وشهادة أن محمدا رسول الله ، معناها القريب : التصديق بأن هذا المنهج الذي بلغه لنا من الله ، هو حقا منهج الله للحياة البشرية ، وهو وحده المنهج الذي نحن ملزمون بتحقيقه في حياتنا وفي حياة البشر جميعا .", "ومن ثم فنحن ملزمون بمحاولة تحقيق ذلك المنهج ؛ لنحقق لأنفسنا صفة الإسلام التي ندعيها . وهى لا تتحقق إلا بشهادة أن لا إله إلا الله ، وأن محمدا رسول الله . وهذه الشهادة لا تقوم إلا بإفراد الله بالألوهية . إفراده بحق وضع منهج الحياة . ومحاولة تحقيق ذلك المنهج الذي جاءنا به محمد صلى الله عليه وسلم من عند الله .", "ونحن ملزمون بمحاولة تحقيق ذلك المنهج لأسباب تتعلق بالمنهج ذاته . فهو وحده المنهج الذي يحقق كرامة «الإنسان» ويمنحه الحرية الحقيقية ، ويطلقه من العبودية .. هو وحده الذي يحقق له التحرر الكامل الشامل المطلق في حدود إنسانيته وعبوديته لله التحرر من"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0020.png"}, {"n": 21, "paras": ["العبودية للناس بالعبودية لله رب الناس .. وما من منهج آخر في الأرض يحقق هذه الخاصية إلا الإسلام .. ذلك أنه بربانيته ، التي تفرد الله سبحانه بالألوهية ، ومن ثم تفرده سبحانه بحق الحاكمية التي تشرع للناس منهج حياتهم .. يجعل للناس إلها واحدا ، وسيدا واحدا . ويمنع أن يكون بعضهم آلهة لبعض ؛ لهم حق الحاكمية بعضهم على بعض ؛ ولهم حق السيادة بعضهم على بعض ، في مقابل العبودية التي يتسم بها من يقرون لهؤلاء الآلهة بخصائص الألوهية !", "وفي هذه الخاصية يتفرد المنهج الإلهى . لا باللفظ والدعوى ، ولكن بالحقيقة والواقع .. ومن ثم كانت دعوة الرسل جميعا عليهم الصلاة والسلام هي إفراد الله بالألوهية ؛ وإنكار كل خاصية من خصائصها على غير الله سبحانه من عبيده ، الذين يتألهون ، فيدعون حق وضع المناهج لحياة عباد الله ؛ ويقرهم على هذا الادعاء من لا يؤمنون بوحدانية الله !", "ولقد قال الله عن اليهود والنصارى : « اتخذوا أحبارهم ورهبانهم أربابا من دون الله والمسيح ابن مريم . وما أمروا إلا ليعبدوا إلها واحدا ، لا إله إلا هو ، سبحانه عما يشركون » .. وهم لم يكونوا يعبدون الأحبار والرهبان ؛ إنما كانوا فقط يقرون لهم بحق التشريع لهم من دون الله ، وبحق وضع المناهج لحياتهم بالتشريع . فقال الله عنهم : إنهم اتخذوهم أربابا . وإنهم خالفوا عن أمر الله لهم بالتوحيد . وإنهم مشركون ..", "روى الإمام أحمد والترمذي وابن جرير من طرق ، عن عدى بن"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0021.png"}, {"n": 22, "paras": ["حاتم - رضى الله عنه أنه لما بلغته دعوة رسول الله صلى الله عليه وسلم فر إلى الشام ، وكان قد تنصر في الجاهلية . فأسرت أخته وجماعة من قومه . ثم منَّ رسول الله صلى الله عليه وسلم على أخته وأعطاها . فرجعت إلى أخيها فرغَّبته فى الإسلام ، وفى القدوم على رسول الله صلى الله عليه وسلم فتقدم عدى إلى المدينة ، وكان رئيسا في قومه طيئ . أبوه حاتم الطائي المشهور بالكرم . فتحدث الناس بقدومه . فدخل على رسول الله صلى الله عليه وسلم وفى عنق عدى صليب من فضة وهو يقرأ هذه الآية : «اتخذوا أحبارهم ورهبانهم أربابا من دون الله» .. قال : فقلت : إنهم لم يعبدوهم . فقال : «بلى ! إنهم حرموا عليهم الحلال ، وأحلوا لهم الحرام ، فاتبعوهم ، فذلك عبادتهم إياهم» !", "وقال السدى : استنصحوا الرجال ، ونبذوا كتاب الله وراء ظهورهم . ولهذا قال تعالى : «وما أمروا إلا ليعبدوا إلها واحدا» ، أى الذى إذا حرم الشئ فهو الحرام ، وما حلله فهو الحلال ، وما شرعه اتبع ، وما حكم به نفذ ...", "والإسلام وحده هو الذى يفرد الله سبحانه بالعبادة ، حين يفرده بالحاكمية وحق وضع المنهج لحياة الناس . ومن ثم فهو وحده الذى يطلق الناس من العبودية لغير الله ... ولهذا فنحن ملزمون بمحاولة تحقيق هذا المنهج دون سواه !", "ونحن ملزمون بمحاولة تحقيق ذلك المنهج ، لأنه بربانيته هو المنهج"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0022.png"}, {"n": 23, "paras": ["الوحيد المبرأ من نتائج الهوى الإنساني ، والضعف الإنساني ، والرغبة الإنسانية فى النفع الذاتى ؛ وفى تحقيق ذلك النفع عن طريق التشريع . لشخص المشرع . أو لأسرته . أو لطبقته . أو لشعبه . أو لجنسه .. فواضع ذلك المنهج هو الله . وهو سبحانه رب البشر أجمعين . فهو لا يشرّع ليحابي نفسه ! ولا ليحابى طبقة من البشر على طبقة ! ولا ليحابى شعبا على شعب ! ولا ليحابى جنسا على جنس !", "والتشريع البشرى ، الذى يصنعه فرد حاكم ، أو أسرة حاكمة ، أو طبقة حاكمة ، أو أمة حاكمة ، أو جنس حاكم ...يستحيل بحسب فطرة الإنسان أن يتجرد من الهوى ، ومن مراعاة مصلحة واضع التشريع .", "فأما حين يكون منهج الله هو الذى يحكم حياة البشر ، فتنتفى هذه الصفة ويتحقق العدل الحقيقى الشامل الكامل ، الذى لا يملك منهج آخر من مناهج البشر أن يحققه فى صورته هذه . لأنه ليس بين هذه المناهج كلها ما يمكن أن يتجرد من عوامل الهوى الإنساني ، والضعف الإنساني والحرص على المصلحة الذاتية فى صورة من الصور .", "وقد يخطر لقائل أن يقول حين يسمع التوجيهات الربانية الرفيعة فى إقرار هذا العدل الشامل الكامل ، الذى لا يتأثر بالهوى ، ولا يتأثر بالعصبية والقرابة من مثل قوله تعالى للجماعة المسلمة : « يأيها الذين آمنوا كونوا قوامين لله شهداء بالقسط ، ولا يجرمنكم شنآن قوم على ألا تعدلوا . اعدلوا هو أقرب للتقوى . واتقوا الله . إن الله خبير بما تعملون » .."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0023.png"}, {"n": 24, "paras": ["قد يخطر لقائل أن يقول : وما هى الضمانات التى تجعل الجماعة المسلمة تحقق هذا العدل الذى يدعوها الله إليه ، ويأمرها به ؟", "والضمانة الحقيقية للمنهج الإسلامى كله كامنة فى ضمير المسلم ؛ منبعثة من إيمانه . فمتى وجد الإيمان بهذا الدين وجدت معه أقوى ضماناته . والمسلمون يتعلمون من دينهم أن مقومات وجودهم وانتصارهم والتمكين لهم فى الأرض ، تقوم كلها على الوفاء بهذه التوجيهات ؛ وإلا تعرض وجودهم للزوال ، وانقلب انتصارهم هزيمة ، وذهبت ريحهم وذلوا . وهم يسمعون الله سبحانه يقول لهم : «ولينصرن الله من ينصره . إن الله لقوى عزيز. الذين إن مكناهم فى الأرض أقاموا الصلاة ، وآتوا الزكاة ، وأمروا بالمعروف ونهوا عن المنكر. ولله عاقبة الأمور» .. ويوقنون أن الله سبحانه لا يحابيهم حين يحيدون عن الطريق .", "والجماعة المسلمة ضمانة حقيقية لتحقيق هذه التوجيهات . فهى تقوم على هذه العقيدة . وتأخذ نفسها بالتزام ما ألزمها الله . وترى فى كل إهمال أو تفريط نذيراً بسوء يلحقها كلها ، ولا يصيب الذين ظلموا منها خاصة ..", "ومن ثم نحن ملزمون بتحقيق ذلك المنهج ، لتحقيق ذلك العدل الشامل الكامل ، الذى لا يتحقق إلا فى ظل هذا المنهج المتفرد .", "ونحن ملزمون بمحاولة تحقيق ذلك المنهج ، لأنه وحده المنهج المبرأ من نتائج الجهل الإنسانى والقصور الإنسانى براءته من نتائج الضعف"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0024.png"}, {"n": 25, "paras": ["البشرى فواضعه هو خالق هذا الكائن الإنساني ، العليم بما يصلحه ويصلح له . وهو المطلع على خفايا تكوينه وتركيبه ، وخفايا الملابسات الأرضية والكونية كلها فى مدى الحياة البشرية كذلك .. فإذا وضع له منهجا كان ملحوظا فى هذا المنهج كل هذه العوامل التي يستحيل على البشر أفرادا ومجتمعين فى جيل من الأجيال وفى جميع الأجيال كذلك أن يطلعوا عليها . لأن بعضها فى حاجة إلى استحضار جميع التجارب والظواهر للحياة البشرية فى جميع أجيالها السابقة والحاضرة ، والمستقبلة التي لم توجد بعد وهذا مستحيل وبعضها فى حاجة إلى الاطلاع على كل خفايا الكون المحيطة بالإنسان وهذا مستحيل كذلك وذلك إلى قصور الإدراك البشرى ذاته عن الحكم الصحيح المطلق حتى على ما يمكن أن تستحضر فيه التجارب والظواهر ! لأنه محكوم بطبيعته الجزئية غير المطلقة ومحكوم بمؤثرات الهوى والضعف الأخرى .. فليس هو إذن بالحكم فى منهج يوضع «للكائن الإنساني» !", "ومن ثم يقول الله تعالى : «ولو اتبع الحق أهواءهم لفسدت السماوات والأرض» .. ويقول : «ثم جعلناك على شريعة من الأمر فاتبعها ولا تتبع أهواء الذين لا يعلمون» ..", "والناس كلهم لا يعلمون .. لا يعلمون ذلك العلم المطلق ، الذى يحتاج إليه وضع منهج للحياة البشرية .. ومن ثم لا يكون لهم إلا الهوى وإلا الجهل حين يتصدون لما ليس من شأنهم ، ولما ليس من اختصاصهم .. فوق ادعائهم لخاصية من خصائص الألوهية .. وهو إثم عظيم . وشر عظيم !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0025.png"}, {"n": 26, "paras": ["ونحن ملزمون بمحاولة تحقيق ذلك المنهج لأنه وحده المنهج الذى يقوم نظام الحياة البشرية فيه على أساس من التفسير الشامل للوجود . ولمكان الإنسان فى هذا الوجود . ولغاية الوجود الإنسانى كما هى فى الحقيقة لا كما يرسمها الجهل والضعف والهوى البشرى ، فى أى تصور آخر غير ربانى .", "وهذا هو الأساس السليم القويم الوحيد لقيام نظام للحياة البشرية على جذوره الطبيعية . فكل نظام لحياة البشر لا يقوم على أساس من هذا التفسير الشامل لا يقوم على جذوره الطبيعية ؛ وهو نظام مصطنع لا يمكن أن يعيش طويلا . وهو مصدر شقاء للبشر طوال مدة قيامه فيهم ، حتى تحطمه فطرتهم وترجع إلى الأصل السليم القويم .", "وهذا التفسير الذى يتضمنه ذلك المنهج الإلهى هو وحده التفسير الصحيح . لأنه من صنع خالق الوجود ، وخالق الإنسان ، العليم بحقيقة الوجود وبحقيقة الإنسان .. وكل تفسير آخر للوجود ، ولمقام الإنسان فيه ، ولغاية الوجود الإنسانى من صنع الإنسان نفسه ، هو تفسير قاصر ، لأن الوجود أكبر من الإنسان . فهناك استحالة فى أن يصنع له الإنسان تفسيراً شاملا . ولأن تحديد غاية الوجود الإنسانى تحتاج إلى علم خالق هذا الإنسان وما أراده من خلقه . كما تحتاج إلى تجرد من الهوى فى تحديد هذه الغاية ! الأمر الذى لا يتيسر للإنسان أبدا .", "والذى يراجع سجل الفلسفة التى حاولت تفسير الوجود ، وتفسير مكان الإنسان فيه ، وتفسير غاية الوجود الإنسانى ، يقع على ركام عجيب . فيه من المضحكات الساذجة بقدر ما فيه من السخف"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0026.png"}, {"n": 27, "paras": ["والافتعال . حتى ليعجب الإنسان : كيف تصدر هذه التصورات عن « فيلسوف » ! ! لولا أن يتذكر أن هذا الفيلسوف إنسان ؛ لا يملك إلا أداة العقل البشرى . وأن هذا ليس مجال العقل البشرى . وأن هؤلاء الناس « الفلاسفة » ! هم الذين زجوا بأنفسهم في مجال لا منارة لهم فيه ، إلا تلك الذبالة الموهوبة لهم من الله لشأن آخر غير هذا الشأن . ولمجال آخر غير هذا المجال . شأن تملك فيه أن تجدى ، ومجال تملك فيه أن تنير .. ذلك هو شأن الحياة الواقعية ، وذلك هو مجال الخلافة في الأرض . وفق المنهج الإلهى . مع التطلع إلى فضل الله وعونه ، فيما يمده به من تفسير شامل للوجود ، ولغاية الوجود الإنساني .. وقوله الفصل وهو الحق .. وقد تضمن منهجه ذلك التفسير بالقدر الذي يقيم عليه التصور الإنساني الصحيح . وبالقدر الذى يقوم عليه كذلك نظام حياته على جذوره الطبيعية .", "فنحن ملزمون بمحاولة تحقيق ذلك المنهج ، ليقوم نظام الحياة البشرية على جذوره الطبيعية . وليس هنالك منهج آخر ، تتوافر فيه هذه الخاصية التى لابد منها .", "ونحن أخيرا ملزمون بمحاولة تحقيق ذلك المنهج لأنه وحده المنهج الذى يتناسق مع نظام الكون كله . فلا ينفرد الإنسان بمنهج لا يتناسق مع ذلك النظام . على حين أنه مضطر أن يعيش فى إطار هذا الكون ؛ وأن يتعامل بجملته مع النظام الكونى .."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0027.png"}, {"n": 28, "paras": ["والتناسق بين منهج حياة الإنسان ومنهج حياة الكون هو وحده الذى يكفل للإنسان التعاون مع القوى الكونية الهائلة ؛ بدلا من التصادم معها . وهو حين يصطدم معها يتمزق وينسحق ، ولا يؤدى وظيفة الخلافة فى الأرض ، كما أرادها الله له . وحين يتناسق مع نواميس الكون ويتوافق ، يملك معرفة أسرارها ، وتسخيرها ، والانتفاع بها فى حياته . لا ليحترق بنار الكون ولكن ليطبخ ويستدفئ ويستضيء ! ! !", "والفطرة البشرية فى أصلها متناسقة مع ناموس الكون .. فحين يخرج الإنسان بنظام حياته عن ذلك الناموس ، فإنه لا يصطدم مع الكون الهائل فحسب ؛ بل يصطدم أيضا بفطرته التى بين جنبيه ، فيشقى ويتمزق ويحتار ويقلق ؛ ويحيا كما تحيا البشرية اليوم فى عذاب نكد ؛ على الرغم من جميع الانتصارات العلمية ، وجميع التيسيرات الحضارية المادية .", "إن هذه البشرية تعانى من الشقاء والقلق والحيرة والاضطراب ، وتهرب من واقعها النفسى بالأفيون والحشيش والمسكرات . وبالسرعة المجنونة ، والمغامرات الحمقاء ؛ و « بالتقاليع » السخيفة ... وذلك على الرغم من الرخاء المادى والإنتاج الوفير والحياة الميسرة ، والفراغ الكثير .. لا بل إن الخواء والقلق والحيرة لتتضاعف كلها كلما تضاعف الرخاء المادى والتيسيرات الحضارية ..", "إن هذا الخواء المرير يطارد البشرية كالشبح الرعيب . يطاردها فتهرب منه . ولكنها تنتهى كذلك إلى خواء مرير .", "وما من أحد يزور البلاد الغنية الثرية المترفة بالتيسيرات الحضارية وفى مقدمتها أمريكا والسويد حتى يكون الانطباع الأول فى حسه أن"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0028.png"}, {"n": 29, "paras": ["هؤلاء قوم هاربون ! هاربون من أشباح تطاردهم . هاربون من ذوات أنفسهم .. وسرعان ما ينكشف له الرخاء المادى والمتاع الحسى والإشباع الجنسى إلى حد التمرغ فى الوحل .. سرعان ما ينكشف له هذا كله عن الأمراض العصبية والنفسية ، والشذوذ الجنسى ، والقلق العصبى ، والمرض والجنون ، والجريمة الشاذة ، وفراغ الحياة من كل تصور إنسانى كريم .", "لقد أحرزت البشرية عن طريق العلم انتصارات ضخمة في عالم الصحة والعلاج من الأمراض الجسمية . فكشفت من الأدوية ووسائل التشخيص والعلاج ما يعد انتصارات رائعة . وبخاصة بعد كشف مركبات السلفا والبنسلين والمايسين ..", "ولقد حققت فى عالم الصناعة والإنتاج ما يشبه الخوارق ... وما تزال فى طريقها صعدا فى هذا المجال .", "ولقد أحرزت انتصارات باهرة فى كشوف الفضاء ، والأقمار الصناعية ، ومحطات الهواء . ومراكب الفضاء ... وما تزال فى الطريق ..", "ولكن ما أثر هذا كله في حياتها ؟ ما أثره في حياتها النفسية ! هل وجدت السعادة ؟ هل وجدت الطمأنينة ؟ هل وجدت السلام ؟ كلا ! لقد وجدت الشقاء والقلق والخوف .. إنها لم تتقدم كذلك في تصور أهداف الحياة الإنسانية ، وغاية الوجود الإنسانى . وحين يقاس تصور الرجل «المتحضر» لغاية وجوده الإنساني ، إلى التصور الإسلامي لهذه الغاية ، تبدو الحضارة الراهنة لعنة تنحط بالشعور الإنساني إلى الحضيض ، وتصغر من اهتماماته وأشواقه وإنسانيته كلها !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0029.png"}, {"n": 30, "paras": ["إنهم في أمريكا مثلا يعبدون آلهة جديدة ؛ يتصورونها غاية الوجود الإنساني . إله المال . وإله اللذة . وإله الشهرة . وإله الإنتاج ! ومن ثم لا يجدون أنفسهم لأنهم لا يجدون غاية وجودهم الإنساني ! وكذلك الحال في الجاهليات الأخرى . التي تعبد آله"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0030.png"}, {"n": 31, "paras": ["مَنْهَجٌ مُيَسَّر", "ثم يقول قائل : ولكن البشرية لم تصبر طويلا على هذا المنهج السامق الفريد . فقد تفلتت منه الجماعة التى حققته فى الأرض فترة من الزمان ؛ وقد اتجهت البشرية بعده إلى مناهج أخرى لا ترتفع إلى تلك القمة السامقة ، ولكنها لا تكلف البشرية هذا الجهد الشاق !", "وقد يبدو هذا القول صحيحا للوهلة الأولى . فقد حرص كثير من الكتاب على تثبيت هذا المعنى فى النفوس ؛ وعلى الإيحاء بأن هذا المنهج غير عملى ولا واقعى ؛ ولا تطيقه طويلا فطرة البشر ؛ وإنما هو دعوة «مثالية» إلى أفق غير مستطاع ! وكان لهم من وراء تثبيت هذا المعنى غرض ماكر ؛ هو إشاعة اليأس من إمكان استئناف الحياة فى ظل هذا المنهج ؛ وتخذيل الجهود التى تبذل لرد البشرية إلى هذا المنهج القويم . ووجد هؤلاء الماكرون فى الفتنة التى بدأت بقتل عثمان رضى الله عنه وما تلاه من الخلاف بين على كرم الله وجهه ومعاوية ، وما أعقب هذا الخلاف من أحداث ... وجدوا فى هذه الفتنة مادة خصبة ؛ وفى الروايات الصحيحة والزائفة عنها فرصة سانحة ، لمحاولة تثبيت ذلك المعنى الخبيث . طورا بالتلميح . وطورا بالتصريح . حسبما واتتهم الظروف !", "وساعدهم فى هذا المكر عن غير قصد وبحسن نية جماعة من"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0031.png"}, {"n": 32, "paras": ["المخلصين الذين ساءهم أن تعترض هذه الفتنة خط المد الإسلامي الصاعد في تلك الفترة التاريخية العظيمة . وأن يقع بعض الانحراف في تصور سياسة الحكم عما كان عليه في عهد رسول الله صلى الله عليه وسلم والشيخين بعده . وأن يقع بعض الانحراف في سلوك بعض الأمراء أيضا .. ومن ثم يحسون بسبب إرهاف مشاعرهم ، أن المد الإسلامي كله قد توقف بعد فترة الخلافة القصيرة ! وينادون بهذه النظرية في حرارة إخلاصهم وشوقهم للقمة السامقة ! وحماستهم للصورة الوضيئة الفريدة !", "وهذا كله يحتاج إلى إعادة النظر ؛ وإلى دقة النظر ؛ وإلى تقدير العوامل البشرية . مع تقدير طبيعة هذا الدين ؛ وطبيعة منهجه لقيادة خطى البشرية في الزمن الطويل ؛ وفي مختلف البيئات ، ومختلف الظروف .", "إنه ليس صحيحا ابتداء أن هذا المنهج الإلهى ، يكلف النفس البشرية جهدا أشق من أن تطيقه أو أن تصبر طويلا عليه .", "إنه منهج سامق فعلا . ولكنه في الوقت ذاته منهج فطرى . يعتمد على رصيد الفطرة ، وينفق من هذا الرصيد المذخور . وميزته أنه يعرف طريقه منذ اللحظة الأولى إلى هذا الرصيد !", "إنه يعرف طريقه إلى النفس البشرية منذ اللمسة الأولى . يعرف دروبها ومنحنياتها فيتدسس إليها بلطف ؛ ويعرف مداخلها ومخارجها فيسلك إليها على استقامة ، ويعرف قواها ومقدراتها فلا يتجاوزها أبدا ؛ ويعرف"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0032.png"}, {"n": 33, "paras": ["حاجاتها وأشواقها فيلبيها تماماً ؛ ويعرف طاقاتها الأصيلة البانية فيطلقها للعمل والبناء ...", "وعلى كل رفعته ونظافته وسموه وسموقه .. هو نظام «للإنسان» . لهذا الإنسان الذي يعيش على سطح هذه الأرض . نظام يأخذ في اعتباره فطرة هذا الإنسان بكل مقوماتها . وخصائص تكوينه وتركيبه بكل مقتضياتها .", "وحين تستقيم النفس مع فطرتها ؛ وحين تلبى حاجاتها وأشواقها ، وحين تطلق طاقاتها للعمل والبناء ، فإنها تجرى مع الحياة في يسر وطواعية ، وتمضى مع خط الفطرة الصاعد ، إلى القمة السامقة ؛ وهى تجد الأنس والاسترواح والطمأنينة والثقة في خط سيرها الطويل .", "وبعض الذين يتشككون ويشككون في إمكان تحقيق هذا المنهج تروعهم «أخلاقية» هذا المنهج ؛ وأصالة العنصر الأخلاقي في تكوينه ؛ وتهولهم تكاليف هذه «الأخلاقية» فيه ؛ ويتصورونها قيودا وكوابح دون انطلاق الإنسان إلى ما يشتهى ؛ وإلى ما تدفعه إليه نوازعه الفطرية وأشواقه !", "وهذا وهم ناشئ من عدم إدراك طبيعة هذا الدين ..", "إن أخلاقية الإسلام لا تتمثل في مجرد مجموعة من القيود والكوابح والضوابط الرادعة . كلا ! إنها في صميمها قوة بناءة ، وحركة دافعة إلى"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0033.png"}, {"n": 34, "paras": ["النمو المطرد ، وانطلاق إلى الحركة وتحقيق الذات في هذه الحركة .. ولكن في أسلوب نظيف ..", "إن العمل والإيجابية صورة أخلاقية في هذا المنهج . فالتبتل والسلبية صورة غير أخلاقية ، لأنها تنافي غاية الوجود الإنساني - كما يصورها الإسلام - وهي الخلافة في الأرض ؛ واستخدام ما سخره الله للإنسان من قواها وطاقاتها في التعمير والبناء .", "والجهاد لتحقيق الخير ومكافحة الشر صورة أخلاقية ؛ تنطلق فيها طاقات أساسية في الكيان الإنساني ؛ بينما هي في اعتبار الإسلام طاعة يتمثل فيها العنصر الأخلاقي في صورة رائعة ..", "وحتى حين نأخذ الصور الأخلاقية التي تبدو في ظاهرها قيودا وكوابح ، فإننا نجدها من الجانب الآخر تمثل صورا من الانطلاق والتحرر .. والحركة ..", "نأخذ مثلا صورة ضبط النفس عن الاندفاع مع الشهوات الجنسية المحرمة .. إنها في ظاهرها تبدو كبتا وكبحا .. ولكنها في حقيقتها تمثل التحرر من العبودية لهذه الشهوات ؛ والانطلاق من عقالها ؛ واستعلاء الإرادة الإنسانية ، بحيث «تختار» مواضع هذه الشهوات ؛ في حدود النظافة التي يوفرها الإسلام ، وفي دائرة الطيبات التي أحلها الله (١) .", "كذلك نأخذ صورة أخرى من صور الأخلاقية .. صورة الإيثار . إنها", "(١) يراجع فصل «مجتمع أخلاقي» في كتاب «نحو مجتمع إسلامي» تحت الطبع . وفصل «القيد والحرية» في كتاب «في النفس والمجتمع» لمحمد قطب ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0034.png"}, {"n": 35, "paras": ["قد تبدو تكليفا للنفس ؛ وكفّاً لها عن التمتع بكل ما تملك ؛ لتؤثر به نفسا أخرى .. ولكنها فى صميمها انطلاق من الشح ؛ واستعلاء على الحرص ؛ وسعة فى الشعور بالخير العام ، الذى لا ينحصر فى إطار الذات .. فهى فى حقيقتها انفلات وتحرر وانطلاق .", "ولا نملك المضي في عرض الأمثلة الكثيرة على هذا النحو، فحسبنا هذه الإشارة ، لفهم حقيقة «القيود» الأخلاقية في المنهج الإسلامي .", "إن الإسلام يعتبر الآثام والرذائل قيودا وأغلالا ، تشد النفس الإنسانية وتثقلها وتهبط بها إلى الوحل . ويعد الانطلاق من أوهاق الميول الهابطة تحررا وانطلاقا ، وكل «أخلاقيته» تقوم على هذا الأساس .", "ذلك أنه يعتبر أن الأصل فى الفطرة هو الاستعداد للخير ؛ فالإنسان خلق في أحسن تقويم . وإنما يرتد أسفل سافلين حين يستسلم لغير منهج الله : «لقد خلقنا الإنسان فى أحسن تقويم . ثم رددناه أسفل سافلين .. إلا الذين آمنوا وعملوا الصالحات» .. ومن ثم فإن المنهج الذي يلائم الفطرة ، هو الذى يعينها على الانفلات من القيود الطارئة على الفطرة الخيرة ، والتحرر من ربقة الشهوات المقيدة !", "والإسلام يحرص على قيادة المجتمع البشرى ، والهيمنة عليه ، لينشىء فيه حالات وأوضاعا تطلق الأفراد من الانحرافات الدخيلة على الفطرة ؛ وتسمح للقوى الخيرة البانية في الفطرة بالظهور والتحرر والتفوق ؛ وتزيل العوائق التي تحول بين الفطرة والانطلاق إلى الخير الذي فطرت عليه .", "والذين يظنون أن «أخلاقية» الإسلام تجعل منه عبئا ثقيلا على"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0035.png"}, {"n": 36, "paras": ["البشرية ، تحول دون تحقيقه فى حياتهم ، إنما يستمدون هذا الشعور مما يعانيه الفرد المسلم ، حين يعيش فى مجتمع لا يهيمن عليه الإسلام .. وحين يكون الأمر كذلك يكون الإسلام بأخلاقيته عبئا ثقيلا فادحا بالفعل ، يقصم ظهور الأفراد الذين يعيشون بإسلامهم النظيف ، فى المجتمع الجاهلى القذر ؛ ويكاد يسحقهم سحقا !", "ولكن هذا ليس هو الوضع الطبيعى الذى يفترضه الإسلام ، وهو يفرض « أخلاقيته » الرفيعة النظيفة السامقة على الناس .. إن الإسلام نظام واقعى . ومن ثم فهو يفترض أن الناس الذين يعيشون بمنهجه ، يعيشون فى مجتمع يهيمن عليه الإسلام . وفى هذا المجتمع يكون الخير والفضيلة والنظافة هى « المعروف » الذى يعرفه ويصونه كل القائمين على هذا المجتمع . ويكون الشر والرذيلة والقذارة هى « المنكر » الذى تطارده كل القوى المهيمنة على هذا المجتمع أيضا !", "وحين يستقيم الأمر على هذا النحو يصبح المنهج الإسلامى للحياة منهجا ميسرا شديد التيسير. بل تصبح الصعوبة الحقيقية هى مخالفة الأفراد لهذا المنهج ؛ ومحاولتهم الاندفاع مع الشهوات الهابطة ؛ ومفارقة الشر والرذيلة . لأن كل القوى المهيمنة على المجتمع حينئذ مضافا إليها قوى الفطرة السليمة المستقيمة تقف فى وجوههم ، وتجعل طريقهم المنحرف شاقا عسيرا !", "ومن هنا يحتم الإسلام أن تكون الهيمنة المطلقة على الجماعة البشرية لله ولمنهج الله ؛ ويحرم أن تكون هذه الهيمنة المطلقة لأحد من خلق الله ، ولمنهج من صنع غير الله . ويعد هذا كفرا صريحا أو شركا كاملا كما"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0036.png"}, {"n": 37, "paras": ["أسلفنا في مقدمات الفصل السابق فالإسلام له صورة واحدة ؛ هي إفراد الله سبحانه بالألوهية .. أي إفراد منهجه بالهيمنة على الحياة البشرية . لأن هذا هو المعنى المباشر القريب لشهادة أن لا إله إلا الله كما أسلفنا .", "كذلك يفترض الإسلام قيام مجتمع إسلامي يعيش في ظله الفرد المسلم بدينه هذا ، وبخلقه الذى يفرضه هذا الدين . ذلك أن الشعور الإسلامي للوجود كله ، ولغاية الوجود الإنساني ، يختلف اختلافا جوهريا عن جميع التصورات الجاهلية وهى التي يصوغها البشر لأنفسهم في معزل عن هدى الله فى أى زمان وفى أى مكان وهو اختلاف رئيسي لا مجال فيه للالتقاء فى منتصف الطريق ..", "فلابد إذن من وسط خاص يعيش فيه هذا التصور ، بكل قيمه الخاصة . لابد له من وسط غير الوسط الجاهلى ؛ ولابد له من بيئة غير البيئة الجاهلية .", "هذا الوسط الخاص يعيش بالتصور الإسلامي ، وبالمنهج الذى ينبثق منه ؛ ويتنفس أنفاسه الطبيعية فى طلاقة وحرية ، وينمو نموه الذاتى بلا عوائق من داخله تؤخر هذا النمو أو تقاومه ؛ وبلا عوائق من خارجه تسحقه أو تطغى عليه .", "وفى هذا الوسط يحيا الفرد المسلم حياة طبيعية مريحة ؛ لأنه يتنفس أنفاسه الطبيعية ؛ ويجد على الخير أعوانا ؛ ويجد في اتباع «الأخلاقية» الإسلامية راحة شعورية ، وراحة اجتماعية ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0037.png"}, {"n": 38, "paras": ["وبغير هذا الوسط تصبح حياة هذا الفرد متعذرة أو شاقة على الأقل ومن هنا ينبغى أن يعلم من يريد أن يكون مسلما ، أنه لا يستطيع أن يزاول إسلامه إلا فى وسط مسلم ، يهيمن عليه الإسلام . وإلا فهو واهم إذا ظن أنه يملك أن يحقق إسلامه ، وهو فرد ضائع أو مطارد فى المجتمعات الجاهلية !", "إن المنهج الإسلامى ميسر ، حين يعيش فى وسطه هذا . وهو يفترض أن هذا الوسط لابد من وجوده . ويقيم توجيهاته كلها على هذا الأساس .", "كذلك ليس صحيحا أن هذا المنهج يكلف البشرية جهداً أشق من الجهد الذى تبذله وهى تحيا فى ظل المناهج الجاهلية ..", "إن المناهج الجاهلية وهى التى يتخذها البشر لأنفسهم فى معزل عن هدى الله فى أى زمان وفى أى مكان تتسم حتما بشىء من نتائج الجهل البشرى والضعف البشرى والهوى البشرى وذلك فى أحسن حالاتها فهى من ثم تصطدم بالفطرة البشرية اصطداما كليا أو جزئيا . ومن ثم تشقى بها النفس بقدر ما فيها من التصادم مع فطرتها !", "ثم إنها تتسم كذلك بالعلاجات والحلول الجزئية للمشكلات البشرية . وكثيرا ما تعالج جانبا بإيذاء الجانب الآخر ؛ وتلك هى الثمرة المباشرة للرؤية الناقصة التى لا تلم بجميع الجوانب فى الوقت الواحد . فإذا عادت إلى علاج الداء الجديد الذى أنشأه العلاج للداء الأول ، أنشأت داء جديدا ... وهكذا دواليك ... كما تشهد بذلك دراسة التقلبات والأطوار التى أنشأتها النظم البشرية والمناهج البشرية ... الجاهلية ... وهذا وذلك"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0038.png"}, {"n": 39, "paras": ["يكلف البشرية ولا شك جهودا أشق من الجهد الذى تبذله للمنهج الكامل الشامل المستقيم مع الفطرة ؛ الذى ينظر إلى مشكلاتها كلها من جميع الجوانب ، ويضع لها العلاج الكامل الشامل ، المنبثق من الرؤية الكاملة الشاملة .", "والذى يراجع سجل الآلام البشرية ، الناشئة من مناهج الجاهلية ، فى تاريخها الطويل ، لا يجرؤ على القول بأن هذا المنهج الإلهى بكل تكاليفه ، وبكل « أخلاقيته » يكلف البشرية من الجهد مالا تكلفه لها المناهج الجاهلية !", "وأيسر ما فى هذا المنهج أنه وهو يضع فى حسابه البلوغ إلى القمة السامقة لا يعتسف الطريق ، ولا يستعجل الخُطى ، ولا يتخطى المراحل .. إن المدى أمامه ممتد فسيح ؛ لا يحده عمر فرد ؛ ولا تستحثه رغبة فان يخشى أن يعجله الموت أو الفوت عن تحقيق غايته البعيدة ؛ كما يقع لأصحاب المذاهب والمناهج الأرضية من البشر الفانين ؛ الذين يعتسفون الأمر كله فى جيل واحد ؛ ويتخطون الفطرة الهادئة الخطى ، ليقفزوا إلى تحقيق صورة براقة تخايل لهم ؛ ولا يصبرون على الخطو الطبيعى الهادئ المطمئن البصير .. وفى الطريق المعتسف الذى يسلكونه تقوم المجازر ، وتسيل الدماء ، وتتحطم القيم ؛ وتضطرب الموازين .. ثم يتحطمون هم فى النهاية تحت مطارق الفطرة التى لا تصمد لها الأجهزة المصطنعة العسوف !", "فأما المنهج الإسلامى فيسير هينا لينا مع الفطرة يوجهها من هنا ، ويذودها من هناك ؛ ويقوّمها حين تميل . ولكنه لا يكسرها ولا يحطمها"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0039.png"}, {"n": 40, "paras": ["ولا يجهدها كذلك . إنه يصبر عليها صبر العارف البصير ، الواثق من الغاية البعيدة المدى ، الأكيدة التحقيق .. والذى لا يتم فى الجولة الأولى يتم فى الجولة الثانية ، والذى لا يتم فى الجولة الثانية يتم فى الجولة الثالثة .. أو العاشرة .. أو المئة .. أو الألف ! كل ما هو مطلوب هو بذل الجهد والمضى فى الطريق !", "وكما تنبت الشجرة الباسقة ، وتضرب بجذورها فى أعماق التربة ، وتتطاول فروعها وتتشابك .. كذلك ينبت هذا المنهج فى النفس والحياة . ويمتد فى بطء ، وعلى هيئة . وفى ثقة وطمأنينة .. ثم يكون ما يريد الله أن يكون .", "إن الإسلام يلقى بذوره ، ويقوم على حراستها ؛ ويدعها حينئذ تنمو نموها الطبيعى الهادئ وهو واثق من الغاية البعيدة . ومهما يحدث من البطء أحيانا ، ومن التراجع أحيانا ، فإن هذا شأن الفطرة .. والزرعة"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0040.png"}, {"n": 41, "paras": ["وأخيرا فإنه ليس صحيحا أن هذا المنهج لم يعش طويلا كما يقول بعضهم في خبث وكيد ، وبعضهم في حماسة وغيرة ! فإن البناء الروحي والاجتماعى والسياسى ، الذى قام على أساس هذا المنهج السامق الفريد ، والذى لم يستغرق بناؤه سوى قرن واحد من الزمان بل نصف قرن في الحقيقة قد ظل يقاوم جميع الآفات التى تسللت إليه ، وجميع العداوات التى ساورته ، وجميع الهجمات الوحشية التى شنت عليه .. أكثر من ألف عام ..", "وقد ظلت هذه العوامل الرهيبة تساوره وتهاجمه وتتسلل إلى قواعده في إصرار .. ووراءها جميع قوى العالم الجاهلي .. فلا تبلغ أن تحطمه من أساسه . ولكنها مع تطاول الزمان ، ومع التجمع والترصد ، ومع الإصرار والاستمرار ، ظلت تنقص منه شيئا فشيئا ، وتنحرف به عن أصوله شيئا فشيئا ؛ حتى أثخنته فعلا وهددته تهديدا خطيرا .. ومع هذا كله فإنها لم تستطع حتى اللحظة تشويه أصوله النظرية ؛ فما تزال هذه الأصول قادرة على البعث الجديد ، حين يعتنقها جيل جديد !", "ولكى ندرك قيمة هذه الحقيقة التاريخية ، ينبغى أن ننظر إلى بناء آخر ، قام على منهج جاهلي .. ذلك هو بناء الدولة الرومانية .. لقد استغرق هذا البناء قرابة ألف عام . ثم تحطم فيما لا يزيد على قرن واحد تحت ضربات الهون والقوط .. ولم يقم بعد ذلك أبدا . ولا بقيت في أصوله بقية ينهض عليها بعث جديد !", "وهذا هو الفارق الأساسي بين منهج الله ومناهج العبيد !", "نعم إنه كانت هناك فترة فارعة في تاريخ هذا المنهج وفى تاريخ"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0041.png"}, {"n": 42, "paras": ["البشرية كله ظلت تتراءى فى التاريخ البشرى كله ، كالقمة السامقة ، تتطاول إليها الأعناق ، وتتطلع إليها الأنظار ، وهى فى مكانها السامى هناك !", ".. وهى فترة قصيرة فعلا ..", "ولكن هذه الفترة ليست هى كل العهد الإسلامى .. إنما هى منارة أقامها الله ، لتظل البشرية تتطلع إليها ، وتحاول أن تبلغها كذلك ؛ وتتجدد آمالها فى بلوغ القمة السامقة ، وهى تدرج إليها فى المرتقى الصاعد . ويقسم الله لها ما يقسم من المدارج فى هذا المرتقى . وهى تتطلع دائما إلى المنارة الهادية !", "حقيقة إن هذه الفترة لم تكن وليدة معجزة لا تتكرر ، وأنها كانت ثمرة الجهد البشرى الذى بذلته الجماعة المسلمة الأولى ؛ وأنها ممكنة التحقيق حين يبذل مثل ذلك الجهد مرة أخرى ..", "ولكن هذا الجهد الذى بذلته طائفة مختارة من البشر ، قد يكون مرصودا لكثير من الأجيال البشرية القادمة لا لجيل واحد وقد يكون تحقيق تلك القمة الفريدة فى ذلك الجيل الواحد ، قدرا من أقدار الله ، لكى يقوم هذا النموذج فى صورة واقعية تمكن محاولتها ، وتمكن معرفة خصائصها .. ثم يترك للبشرية بعد ذلك فى أجيالها المتتابعة ، أن تحاول بلوغها من جديد ..", "وقد ظل المنهج يؤدى دوره ، فيما بعد هذه الفترة ، فى مساحات واسعة من الحياة البشرية ؛ وظل يفعل فى تصورات البشرية وتاريخها"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0042.png"}, {"n": 43, "paras": ["وواقعها أجيالا طويلة ؛ وترك من ورائه آثارا وتيارات في حياة البشرية كلها ، لعلها هي التي تجعلنا نأمل اليوم ، في إمكان البشرية أن تتطلع إلى المحاولة من جديد ..."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0043.png"}, {"n": 44, "paras": ["مَنْهَجٌ مُؤَثّر", "على أن هذه الإشراقة اللامعة ، بلغت من التأثير الدائم فى واقع الحياة البشرية ، قدر ما بلغته من البهاء والرفعة ، ومن العظمة والكمال . وخلفت فى واقع البشرية التاريخى من الآثار الباقية ، ما قد يجعل الجيل الحاضر من هذه البشرية اليوم أقدر على المحاولة من سائر الأجيال التى خلت بعد تلك الصفوة المختارة من رجال الصدر الأول وذلك بمساعدة التيارات التى أطلقتها ، والرواسب التى خلفتها ؛ فى التصورات والقيم ، وفى النظم والأوضاع سواء .", "وسنحاول فى هذا الفصل أن نلم فى اختصار وإجمال يناسبان طبيعة هذا البحث المجمل المختصر بلمحات عن آثار هذه الإشراقة الوضيئة الفريدة ، لا فى تاريخ الأمة الإسلامية وحدها ، ولكن كذلك فى تاريخ البشرية بجملتها .", "لقد استطاعت تلك الفترة أن تنشئ فى واقع الحياة البشرية عددا كبيرا من الشخصيات النموذجية ؛ تتمثل فيها الإنسانية العليا ، بصورة غير مسبوقة ولا ملحوقة . صورة تبدو فى ظلها جميع الشخصيات البشرية التى نشأت فى غير هذا المنهج ، أقزاما صغيرة ، أو كائنات لم تستكمل وجودها"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0044.png"}, {"n": 45, "paras": ["بعد ، أو كائنات غير متناسقة على كل حال !", "ولم تكن هذه الشخصيات النموذجية التى أخرجها المنهج الإلهى فى تلك الفترة القصيرة آحادا تعد على أصابع اليدين ؛ إنما كانت حشدا كبيرا ؛ يعجب الباحث كيف انبثقت هكذا سامقة ناضجة إلى هذا المستوى العجيب ؛ فى هذه الفترة القصيرة المحدودة . ويعجز عن تعليل انبثاقها على هذا النطاق الواسع ؛ وعلى هذا المستوى الفارع ؛ وفى مثل هذا التنوع فى النماذج .. ما لم يرد هذه الظاهرة الفريدة إلى فعل ذلك المنهج الفريد .", "والمهم أن نعرف أن هؤلاء الناس ، الذين تمثلت فيهم نماذج الإنسانية العليا : النماذج التى ظلت فريدة فى سموقها ؛ وظلت سائر النماذج على مدار القرون تبدو فى ظلها أقزاما صغيرة ، أو كائنات غير تامة الوجود .. المهم أن نعرف أن هؤلاء الناس الذين حققوا ذلك المنهج الإلهى فى حياتهم على هذا النحو العجيب ، قد ظلوا مع هذا ناسا من البشر لم يخرجوا عن طبيعتهم ، ولا عن فطرتهم ؛ ولم يكبتوا طاقة واحدة من طاقاتهم البانية ؛ ولم يكلفوا أنفسهم كذلك فوق طاقتهم .. لقد زاولوا كل نشاط إنسانى ، وأصابوا من الطيبات كل ما كان متاحا لهم فى بيئتهم وزمانهم .. لقد أخطأوا وأصابوا ، وعثروا ونهضوا ؛ وأصابهم الضعف البشرى أحيانا كما يصيب سائر البشر وغالبوا هذا الضعف ، وانتصروا عليه أحيانا أخرى ..", "والمعرفة بهذه الحقيقة ذات أهمية قصوى . فهى تعطى البشرية أملا قويا فى إعادة المحاولة ؛ وتجعل من واجبها بل تجعل من حقها أن"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0045.png"}, {"n": 46, "paras": ["تتطلع إلى هذه الصورة الوضيئة الممكنة ، وأن تظل تتطلع . فهى صوره من شأنها أن تزيد من ثقة البشرية بنفسها ، وبفطرتها ، وبمقدراتها الكامنة ، التى يمكن عندما يوجد المنهج الصالح أن تبلغ بها إلى ذلك المستوى الإنسانى الرفيع ، الذى بلغته مرة فى تاريخها .. فهى لم تبلغه بمعجزة خارقة لا تتكرر . إنما بلغته فى ظل منهج من طبيعته أن يتحقق بالجهد البشرى ، وفى حدود الطاقة البشرية . ولقد انبثق ذلك الجيل الفارع العظيم ، من قلب الصحراء ، الفقيرة الموارد ، المحدودة المقدرات الطبيعية والاقتصادية والعلمية .. وعلى كل ما كان فى هذه البيئة من الموافقات المكونة لهذا الانبثاق الهائل العجيب ، فإن البشرية اليوم وغداً ليست عاجزة بفطرتها ، ولا عاجزة بمقدراتها ، أن تنجح مرة أخرى فى المحاولة ، إذا هى اتخذت ذلك المنهج قاعدة لحياتها . ولقد ظل هذا المنهج على كل ما ألم به على مدى الزمن من انحرافات ومن خصومات ومن هجمات يبعث بنماذج من الرجال ، فيها من ذلك الجيل الأول الفارع مشابه ؛ وفيها منه آثار وانطباعات .. وظلت هذه النماذج تؤثر فى الحياة البشرية تأثيرات قوية ؛ وتؤثر فى خط سير التاريخ البشرى ؛ وتترك من حولها ومن ورائها تيارات ودوامات هائلة تطبع وجه الحياة ؛ وتلون سماتها . وما يزال هذا المنهج قادرا فى كل حين ، على أن يبعث بهذه النماذج ، كلما بذلت محاولة جدية فى تطبيقه وتحكيمه فى الحياة . على الرغم من جميع المؤثرات المضادة ؛ وعلى الرغم من جميع المعوقات من حوله وفى طريقه ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0046.png"}, {"n": 47, "paras": ["والسر الكامن فيه هو تعامله المباشر مع الفطرة ؛ واستمداده المباشر من رصيدها المكنون . وهو رصيد هائل ، ورصيد دائم . وحيثما التقى مع هذا المنهج تفجرت ينابيعه الثرة ؛ وفاض فيضه المكنون !", "واستطاعت هذه الفترة أن تقرر في واقع الحياة البشرية مبادئ وتصورات ، وقيما وموازين ، لم يسبق أن تقررت في تاريخها كله ، بمثل هذا الوضوح ، وبمثل هذا العمق ، وبمثل هذا الشمول للنشاط الحيوى كله . ولم يقع كذلك أن تقررت هذه المبادئ والتصورات والقيم والموازين في واقع البشرية مرة أخرى وفي ظل أى منهج وأى نظام في الأرض كلها بمثل هذا الوضوح ، وبمثل هذا العمق ، وبمثل هذا الشمول للنشاط الحيوى كله .. ثم وهذا هو الأهم بمثل هذا الصدق والجد والإخلاص والتجرد الحقيقي العميق .", "وقد تناولت هذه المبادئ والتصورات . وهذه القيم والموازين ، كل قطاعات الحياة الإنسانية . تناولت تصور البشرية لإلهها ، وعلاقاتها به . وتصورها لهذا الوجود الذي تعيش فيه وعلاقاتها به ، وتصورها لغاية وجودها الإنساني ومكانها في هذا الكون ووظيفتها ...", "كما تناولت تبعا لذلك تصورها لحقيقة الإنسان ، وحقوقه وواجباته وتكاليفه ، والقيم التي توزن بها حياته ونشاطه ومكانته ، والتي تقوم عليها علاقاته بربه ، وعلاقاته بأهله ، وعلاقاته بأبناء جنسه ، وعلاقاته بالكون والأحياء والأشياء ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0047.png"}, {"n": 48, "paras": ["ومما تناولته .. الحقوق والواجبات السياسية والاجتماعية والاقتصادية ، والأنظمة والأوضاع والروابط التى تنظم هذه الحقوق والواجبات وبالجملة كل قطاعات الحياة الإنسانية فى شتى صورها وجوانبها الكثيرة .", "وقررت فى هذا كله حكمها الذى يفردها ويميزها ، ويجعل لها طابعها الربانى الفريد ..", "وقد تم هذا كله فى وسط محلى معادٍ لمثل هذه المبادئ والتصورات ؛ ولهذه القيم والموازين .. وفى وسط عالمى منكر لأساس هذه المبادئ والتصورات والقيم والموازين . وفى ظروف اقتصادية واجتماعية وسياسية وعقلية ونفسية محلية وعالمية من شأن ظواهرها أن تصادم هذه الاتجاهات التى قررها الإسلام فى واقع الحياة البشرية ، للمرة الأولى ، أو على الأقل لا تساعدها على الحركة الطليقة . معتمدا فى نجاحه قبل كل شيء على رصيد الفطرة البشرية من الاستعداد للاستقامة على المنهج الإلهى الموافق فى صميمه لهذه الفطرة قبل أن تغشيها المؤثرات السطحية وعلى استثارة هذا الرصيد ، واستنقاذه من الركام الذى ران عليه . وهو رصيد ضخم ، يكفى حين يوجد المنهج الذى يستنقذه من التبدد والانطمار لمقاومة تلك المؤثرات السطحية ، التى يظن بعض قصار النظر أنها تمثل كل شيء فى حياة الإنسان .. والإسلام لا يغفل هذه المؤثرات ولا يهمل آثارها فى الحياة البشرية . ولكنه لا يقف أمامها مستسلما ، باعتبارها « أمرا واقعاً » لا فكاك منه . بل يلجأ إلى استنقاذ رصيد الفطرة ؛ وتجميعه ، وتوجيهه ، لتعديل الواقع ، فى رفق وتؤدة على نحو ما بينا من طريقته فى العمل فى الفصل السابق وينتهى إلى مثل"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0048.png"}, {"n": 49, "paras": ["ما انتهى إليه فى تلك الفترة ، فى مواجهة تلك الظروف المناوئة ، المحلية والعالمية ، وتحويلها إلى ظروف مواتية . كما حدث بالفعل فى الجزيرة العربية ، وفيما وراءها كذلك !", "والبشرية اليوم قد تكون فى بعض الجوانب أحسن حالا وظروفا منها يوم جاءها هذا المنهج ، وأحدث فيها فى فترة قصيرة ذلك الانقلاب الشامل ، وتلك الثورة العظمى فى رفق ويسر وانطلاق وقد تكون أقدر على العمل بهذا المنهج للأسباب التى سنبديها فى فصل تال وقد تكون طاقتها اليوم على حمله أكبر . وبخاصة حين نعرف أن رصيد الفطرة الإنسانية على الرغم من كل ما يرسب فوقه من ركام الفساد والشر والانحراف ؛ وعلى الرغم من كل ما يبدده ويسحقه من الأوضاع المادية والمؤثرات الاقتصادية والفكرية قادر على أن ينتفض ، ويتجمع ، ويعمل ، حين يفلح المنهج فى استنقاذه وتجميعه وتوجيهه ، وإطلاقه فى الخط المتناسق مع فطرة الإنسان ، وفطرة الكون ، كما خلقها الله . وأن هذا الرصيد من الأصالة ، والعمق ، والضخامة ، بحيث يرجح سائر العوامل الأخرى ، التى تأخذ صورة « الواقع » ... فما بال إذا كان بعض هذه العوامل اليوم فى صفه وفى اتجاهه ؟", "إن « الواقع » الخارجى يتراءى ، لمن لا يعرفون طبيعة هذا المنهج ، كما لو كان هو الحقيقة التى لا سبيل إلى تغييرها، ولا سبيل إلى زحزحتها .، ولا سبيل إلى التمرد عليها !", "ولكن هذا ليس إلا وهما كبيرا . فالفطرة البشرية « واقع » كذلك . وهى ليست على استقامة مع هذا الواقع الظاهرى ؛ بدليل أنها تشقى به"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0049.png"}, {"n": 50, "paras": ["في مشارق الأرض ومغاربها . وحين تصطدم الفطرة بوضع من الأوضاع ، أو بنظام من النظم ، فقد تُغلب في أول الأمر ؛ لأن وراء هذا الوضع أو هذا النظام قوة مادية تفرضه فرضاً ؛ ولكن الذي لاشك فيه أن الفطرة أقوى وأثبت من كل وضع طارئ عليها ، ومن كل قوة تسند هذا الوضع الطارئ . ولابد لها من أن تغلب في النهاية . وبخاصة حين يقودها منهج طبيعته من طبيعتها ..", "وقد حدث هذا مرة يوم واجه ذلك المنهج الإلهي « واقع » الجزيرة العربية ، وواقع الأرض كلها . فانتصر على هذا الواقع انتصارا رائعا ؛ وبدّل قوائمه التصورية والعملية ؛ وأقامه على أسس جديدة .", "وهذا الذي حدث لم يتم بمعجزة خارقة لا تتكرر . ولكنه تحقق وفق سنة الله الدائمة بجهد بشرى ، وفى حدود الطاقة البشرية ... فدلت هذه السابقة على إمكان تكرار هذه الظاهرة .", "فما بال إذا كانت التيارات التي أطلقتها تلك الفترة ، والرواسب التي خلفتها ، في حياة البشرية ، وفى الواقع التاريخي ، كلها عوامل مساعدة في المحاولة الجديدة ؟", "واستطاعت تلك الفترة أن تقر في حياة البشرية تقاليد عملية ، وأوضاعا واقعية تستند إلى تلك المبادئ والتصورات والقيم والموازين لم تمت وتذهب بانقضاء تلك الفترة . ولكنها امتدت في صورة تيار متحرك ، مندفع إلى مسافات بعيدة في الأرض ؛ وإلى أحقاب متطاولة"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0050.png"}, {"n": 51, "paras": ["من الزمان . وتأثرت بها الحياة البشرية كلها على صورة من الصور وأصبحت رصيدا للبشرية كلها ، تنفق منه وتستمد أكثر من ألف عام .. رصيدا يؤثر فى تصوراتها ، ويؤثر فى أوضاعها ، ويؤثر فى تقاليدها ، ويؤثر فى علومها ومعارفها ، ويؤثر فى اقتصادها وعمرانها ، ويؤثر فى حضارتها كلها تأثيرات متفاوتة ؛ ولكنها مطردة فاعلة فى كل ركن من أركان الأرض . وما تزال بقايا من ذلك التيار تعمل فى واقع الحياة البشرية حتى اليوم ، على الرغم من جميع القوى التى وقفت فى وجه هذا المد الغامر ، وعلى الرغم من النكسة أو النكسات إلى الجاهلية الإغريقية والجاهلية الرومانية ، فى العالم الغربى ، الذى سيطر على مقاليد الأرض أحقابا متطاولة !", "وقد استقرت فى حياة البشرية من وراء هذه التأثيرات الواقعية مبادئ وقيم ، ونظريات وأوضاع ، قد تجهل البشرية اليوم مصدرها الأصيل ، وقد تردها إلى مصادر أخرى غير ذلك المنهج المؤثر . ولكنه ليس من المتعذر معرفة أصلها الأول ، والرجوع بها إلى فعل المنهج الإلهى ، وآثاره فى الحياة البشرية . وسنشير فى فصل تال إلى بعض الخطوط العريضة التى انتهت البشرية إلى إقرارها اليوم ، وكانت منكرة لها أشد الإنكار يوم جاءها بها الإسلام ، أول مرة ، منذ نيف وثلثمائة وألف عام !", "ولعله من شأن استقرار هذه الخطوط العريضة فى حياة البشرية وأوضاعها الحاضرة ، بعد الإنكار الشديد لها يوم جاءها بها الإسلام أول مرة ، أن تكون البشرية اليوم أقرب بصفة عامة إلى تفهم هذا المنهج ، وأقدر كذلك على حمله ، ولديها منه رصيد واقعى ، خلفته"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0051.png"}, {"n": 52, "paras": ["موجة المد الأولى ، لم يكن لديها يوم جاءها أول مرة ! ولديها كذلك رصيد من تجاربها الخاصة ، في فترة التيه والشرود عن هذا المنهج ؛ وما أصبحت تعانيه اليوم من آثار هذا التيه وهذا الشرود مما سبقت الإشارة إليه باختصار فهذه وتلك قد تكون من العوامل المساعدة على تقبل المنهج الإلهي ، والصبر عليه في الجولة القادمة ... بإذن الله ..", "ولعله يحسن الآن وقد وصلنا إلى هذا الحد من الإشارات المجملة أن نفصلها بعض التفصيل ، بذكر شيء من مدلولاتها الواقعية في الحياة البشرية ، من خلال الواقع التاريخي ، وبتفصيل شيء عن رصيد الفطرة الذي واجه به الإسلام واقع البشرية فانتصر عليه ، وقرر منهجه في وجه ذلك الواقع .."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0052.png"}, {"n": 53, "paras": ["رَصِيدُ الفطرة", "يوم جاء الإسلام أول مرة وقف فى وجهه «واقع» ضخم . واقع الجزيرة العربية ، وواقع الكرة الأرضية ! .. وقفت فى وجهه عقائد وتصورات ؛ ووقفت فى وجهه قيم وموازين ؛ ووقفت فى وجهه أنظمة وأوضاع ؛ ووقفت فى وجهه مصالح وعصبيات ...", "كانت المسافة بين الإسلام يوم جاء وبين واقع الناس فى الجزيرة العربية وفى الكرة الأرضية ، مسافة هائلة سحيقة . وكانت النقلة التى يريدهم عليها بعيدة بعيدة ...", "وكانت تسند «الواقع» أحقاب من التاريخ ؛ وأشتات من المصالح ؛ وألوان من القوى ؛ وتقف كلها سدا فى وجه هذا الدين الجديد ؛ الذى لا يكتفى بتغيير العقائد والتصورات ، والقيم والموازين ، والعادات والتقاليد ، والأخلاق والمشاعر .. إنما يريد كذلك ويصر على أن يغير الأنظمة والأوضاع ، والشرائع والقوانين ، وتوزيع الأموال والأرزاق . كما يصر على انتزاع قيادة البشرية من يد الطاغوت والجاهلية ، ليردها إلى الله وإلى الإسلام !", "ولو أنه قيل لكائن من كان فى ذلك الزمان إن هذا الدين الجديد الذى يحاول هذا كله ، فى وجه ذلك «الواقع» الهائل ، الذى"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0053.png"}, {"n": 54, "paras": ["تسنده قوى الأرض كلها ، هو الذي سينتصر ، وهو الذي سيبدل هذا الواقع في أقل من نصف قرن من الزمان ، لما لقى هذا القول إلا السخرية والاستهزاء والاستنكار !", "ولكن هذا « الواقع » الهائل الضخم ، سرعان ما تزحزح عن مكانه ، ليخليه للوافد الجديد . وسرعان ما تسلم القائد الجديد مقادة البشرية ليخرجها من الظلمات إلى النور ؛ ويقودها بشريعة الله ، تحت راية الإسلام !", "كيف وقع هذا الذي يبدو مستحيلا في تقدير من يبهرهم « الواقع » ويسحقهم ثقله ، وهم يزنون الأمور والأوضاع ؟ ! .", "كيف استطاع رجل واحد . محمد بن عبد الله صلى الله عليه وسلم .. أن يقف وحده في وجه الدنيا كلها ، أو على الأقل في وجه الجزيرة العربية كلها في أول الأمر ؟ أو على الأقل في وجه قريش سادة العرب كلهم في منشأ الدعوة ؟ وأمام تلك العقائد والتصورات ، والقيم والموازين ، والأنظمة والأوضاع ، والمصالح والعصبيات .. ثم ينتصر على هذا كله ؛ ويبدل هذا كله ؛ ويقيم النظام الجديد ، على أساس المنهج الجديد ، والتصور الجديد ؟", "إنه لم يتملق عقائدهم وتصوراتهم ؛ ولم يداهن مشاعرهم وعواطفهم ؛ ولم يهادن آلهتهم وقيادتهم .. لم يتمسكن حتى يتمكن .. إنه أمر أن يقول لهم منذ الأيام الأولى ، وهو في مكة ، تتألب عليه جميع القوى :"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0054.png"}, {"n": 55, "paras": ["« قل ياأيها الكافرون . لا أعبد ماتعبدون . ولا أنتم عابدون ما أعبد . ولا أنا عابد ما عبدتم ولا أنتم عابدون ما أعبد . لكم دينكم ولى دين » ..", "فلم يكتف بأن يعلن لهم افتراق دينه عن دينهم ، وعبادته عن عبادتهم ، ومفاصلتهم في هذا مفاصلة كاملة لالقاء فيها . بل أمر كذلك أن ييئسهم من إمكان هذا اللقاء في المستقبل . فكرر عليهم : « ولا أنا عابد ما عبدتم ولا أنتم عابدون ما أعبد » .. وباطراد المفاصلة في هذا الأمر ، الذى لا التقاء فيه ! « لكم دينكم ولى دين » ..", "وهو كذلك لم يبهرهم بادعاء أن له سلطانا سريا ؛ ولا مزايا غير بشرية ولا موارد سرّية . بل أمر أن يقول لهم :", "« قل : لا أقول لكم عندى خزائن الله ، ولا أعلم الغيب ، ولا أقول لكم إنى ملك . إن أتبع إلا ما يوحى إلى » .. (الأنعام : ٥٠)", "ولم يوزع الوعود بالمناصب والمغانم لمن يتبعونه ، حين ينتصر على مخالفيه : قال ابن إسحاق : « كان النبي - صلى الله عليه وسلم - يعرض نفسه على القبائل فى الموسم - موسم الحج - يقول : « يابنى فلان . إنى رسول الله إليكم ، يأمركم أن تعبدوه ولا تشركوا به شيئا ؛ وأن تخلعوا ما تعبدون من دونه من هذه الأنداد ؛ وأن تؤمنوا بى وتصدقوا بى ؛ وتمنعونى حتى أبين عن الله ما بعثنى به »", "قال ابن إسحاق : وحدثني الزهرى : أنه أتى بنى عامر بن صعصعة ، فدعاهم إلى الله عز وجل ؛ وعرض عليهم نفسه . فقال رجل"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0055.png"}, {"n": 56, "paras": ["منهم يقال له : بيجرة بن فراس : والله لو أني أخذت هذا الفتى من قريش لأكلتُ به العرب ! ثم قال له : أرأيت إن نحن بايعناك على أمرك ، ثم أظهرك الله على من خالفك ، أيكون لنا الأمر من بعدك؟ قال : « الأمر لله يضعه حيث يشاء » . قال : فقال له ، أفَنَهدف نحورنا للعرب ، فإذا أظهرك الله كان الأمر لغيرنا ؟ لا حاجة لنا بأمرك ! فأبوا عليه » ..", "كيف إذن وقع الذي وقع ؟ كيف قوى ذلك الرجل الواحد على قهر كل ذلك « الواقع » ؟", "إنه لم يقهره بمعجزة خارقة لا تتكرر . فقد أعلن صلى الله عليه وسلم أنه لا يعمل فى هذا الحقل بخارقة ، ولم يستجب مرة واحدة لطلبهم للخوارق .. إنما وقع الذي وقع وفق سنة دائمة تتكرر كلما أخذ الناس بها واستجابوا إليها ..", "لقد وقع الذي وقع من غلبة هذا المنهج ، لأنه تعامل من وراء الواقع الظاهرى مع رصيد الفطرة المكنون . وهو رصيد كما أسلفنا ضخم هائل ، لا يغلبه هذا الركام الظاهرى ؛ حين يُستنقَذ ويُجمَع ويُوجَّه ، ويُطلَق فى اتجاه مرسوم !", "كانت المعتقدات الفاسدة والمنحرفة ترين على ضمير البشرية . وكانت الآلهة الزائفة تزحم فناء الكعبة كما تزحم تصورات الناس وعقولهم وقلوبهم . وكانت المصالح القبلية والاقتصادية تقوم على كواهل هذه الآلهة الزائفة ، وما وراءها من سدانة وكهانة ، ومن أوضاع فى حياة الناس ،"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0056.png"}, {"n": 57, "paras": ["مستمدة من توزيع خصائص الألوهية بين العباد ؛ وإعطاء السدنة والكهنة حق الاشتراع للناس ، ووضع مناهج الحياة ! ! !", "وجاء الإسلام يواجه هذا « الواقع » كله بلا إله إلا الله . ويخاطب الفطرة التى لا تعرف لها إلها إلا الله . ويعرف الناس بربهم الحق ، وخصائصه وصفاته التى تعرفها فطرتهم من تحت الأنقاض والركام .", "« قل : أغير الله أتخذ وليا فاطر السماوات والأرض ، وهو يطعم ولا يطعم ؟ قل : إنى أمرت أن أكون أول من أسلم . ولا تكونن من المشركين . قل : إنى أخاف إن عصيت ربى عذاب يوم عظيم . من يصرف عنه يومئذ فقد رحمه ، وذلك الفوز المبين . وإن يمسسك الله بضر فلا كاشف له إلا هو ، وإن يمسسك بخير فهو على كل شئ قدير . وهو القاهر فوق عباده ، وهو الحكيم الخبير . قل : أى شئ أكبر شهادة ؟ قل : الله شهيد بينى وبينكم ؛ وأوحى إلى هذا القرآن لأنذركم به ومن بلغ . أئنكم لتشهدون أن مع الله آلهة أخرى ؟ قل : لا أشهد . قل : إنما هو إله واحد ، وإننى برئ مما تشركون » ( الأنعام ١٤ — ١٩ )", "« قل : إنى نهيت أن أعبد الذين تدعون من دون الله : قل : لا أتبع أهواءكم . قد ضللت إذن وما أنا من المهتدين . قل : إنى على بينة من ربى . وكذبتم به ، ما عندى ما تستعجلون به . إن الحكم إلا لله ، يقص الحق وهو خير الفاصلين . قل : لو أن عندى ما تستعجلون به لقضى الأمر بينى وبينكم ، والله أعلم بالظالمين . وعنده مفاتح الغيب لا يعلمها إلا هو ، ويعلم ما فى البر والبحر ، وما تسقط من ورقة إلا"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0057.png"}, {"n": 58, "paras": ["يعلمها ، ولا حبة فى ظلمات الأرض ، ولا رطب ولا يابس إلا فى كتاب مبين . وهو الذى يتوفاكم بالليل ، ويعلم ما جرحتم بالنهار ، ثم يبعثكم فيه ليُقضى أجل مسمى ، ثم إليه مرجعكم ، ثم ينبئكم بما كنتم تعملون ، وهو القاهر فوق عباده ، ويرسل عليكم حفظة ، حتى إذا جاء أحدكم الموت توفته رسلنا وهم لا يفرطون . ثم ردوا إلى الله مولاهم الحق . ألا له الحكم ، وهو أسرع الحاسبين . قل : من ينجيكم من ظلمات البر والبحر ، تدعونه تضرعا وخفية : لئن أنجانا من هذه لنكونن من الش"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0058.png"}, {"n": 59, "paras": ["لقد كان هناك « واقع » اجتماعى ، وراءه مصالح طبقية وعنصرية ، مادية ومعنوية . واقع سائد فى الجزيرة العربية ، وسائد فى الأرض من حولها . واقع ليس محل اعتراض أحد ، لأن المنتفعين به لا يسأمونه ، والرازحين تحته لا ينكرونه !", "كانت قريش تسمى نفسها « الحمس » وتفرض لنفسها حقوقا وتقاليد ليست لسائر العرب . وتقف فى الحج بالمزدلفة حين يقف الناس جميعا بعرفات ! ويقيمون على هذه الامتيازات منافع اقتصادية يفرضونها على سائر العرب . فيحتمون عليهم ألا يطوفوا بالبيت إلا فى ملابس يشترونها من قريش ؟ وإلا طافوا بالبيت عراة ؟", "وكانت الأرض كلها من حول الجزيرة تعج بالتفرقات القائمة على اختلاف الدماء والأجناس وتفاضلها ..", "« كان المجتمع الإيرانى مؤسسا على اعتبار النسب والحرف . وكان بين طبقات المجتمع هوة واسعة لا يقوم عليها جسر ، ولا تصل بينها صلة . وكانت الحكومة تحظر على العامة أن يشترى أحد منهم عقارا لأمير أو كبير . وكان من قواعد السياسة الساسانية أن يقنع كل واحد بمركزه الذى منحه نسبه ، ولا يستشرف لما فوقه . ولم يكن لأحد أن يتخذ حرفة غير الحرفة التى خلقه الله لها . وكان ملوك إيران لا يولون وضيعا وظيفة من وظائفهم . وكان العامة كذلك طبقات متميزة بعضها عن بعض تميزا واضحا ، وكان لكل واحد مركز محدد فى المجتمع » (١)", "(١) عن كتاب إيران فى عهد الساسانيين تأليف البروفسور أوزنهر سين . نقلا عن كتاب : ماذا خسر العالم بانحطاط المسلمين للأستاذ السيد أبو الحسن الندوى ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0059.png"}, {"n": 60, "paras": ["« وكانت الأكاسرة ملوك فارس يدعون أنه يجرى فى عروقهم دم إلهى . وكان الفرس ينظرون إليهم كآلهة ، ويعتقدون أن في طبيعتهم شيئاً علوياً مقدسا فكانوا يكفّرون لهم ، وينشدون الأناشيد بألوهيتهم ، ويرونهم فوق القانون ، وفوق الانتقاد ، وفوق البشر ، لا يجرى اسمهم على لسانهم ، ولا يجلس أحدهم فى مجلسهم ؛ ويعتقدون أن لهم حقا على كل إنسان ، وليس لإنسان حق عليهم . وأن ما يرضخون لأحد من فضول أموالهم وفتات نعمهم فإنما هو صدقة وتكرم ، من غير استحقاق ، وليس للناس قبلهم إلا السمع والطاعة . وخصصوا بيتاً معيناً وهو بيت الكيانى فكانوا يعتقدون أن لأفراده وحدهم الحق أن يلبسوا التاج ، ويجبوا الخراج . وهذا الحق ينتقل فيهم كابرا عن كابر ، وأبا عن جد ، لا ينازعهم ذلك إلا ظالم ، ولا ينافسهم إلا دعىّ نذل . فكانوا يدينون بالملك وبالوراثة فى البيت المالك ، لا يبغون به بدلا ، ولا يرون عنه محيصا . فإذا لم يجدوا من هذه الأسرة كبيرا ملكوا عليهم طفلا . وإذا لم يجدوا رجلا ملكوا عليهم امرأة . فقد ملكوا بعد «شيرويه » ولده «أردشير» وهو ابن سبع سنين . وملك « فرخ زاد خسرو بن كسرى أبرويز » وهو طفل . وملكوا بوران بنت كسرى . وملكت كذلك ابنة كسرى ثانية يقال لها : « ازرمی دخت » ولم يخطر ببالهم أن يملكوا عليهم . قائدا كبيرا ، أو رئيسا من رؤسائهم ، مثل « رستم » و «جابان » وغيرهما . لأنهم ليسوا من البيت الملكى ! » (١)", "(١) عن كتاب : ماذا خسر العالم بانحطاط المسلمين للسيد أبو الحسن الندوى ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0060.png"}, {"n": 61, "paras": ["وكان نظام الطبقات فى الهند من أعنف وأبشع ما يصنع الإنسان بالإنسان .", "« وقبل ميلاد المسيح بثلاثة قرون ازدهرت فى الهند الحضارة البرهمية ؛ ووضع فيها مرسوم جديد للمجتمع الهندى ، وألف فيه قانون مدنى سياسى اتفق عليه ، وأصبح قانونا رسميا ، ومرجعا دينيا . فى حياة البلاد ومدنيتها ، وهو المعروف الآن : « منوشاستر » ..", "« يقسم هذا القانون الأهالى إلى أربع طبقات متميزة . وهى :", "( ١ ) البراهمة : طبقة الكهنة ورجال الدين . ( ٢ ) شترى : رجال الحرب .", "( ٣ ) ويش : رجال الزراعة والتجارة . ( ٤ ) شودر : رجال الخدمة .", "ويقول « منو » مؤلف هذا القانون :", "« إن القادر المطلق قد خلق لمصلحة العالم البراهمة من فمه ، وشترى من سواعده وويش من أفخاذه ، والشودر من أرجله ! ووزع لهم فرائض وواجبات لصلاح العالم . فعلى البراهمة تعليم « ويد »(١) أو تقديم النذور للآلهة ، وتعاطى الصدقات . وعلى « الشترى » حراسة الناس ، والتصدق وتقديم النذور ودراسة « ويد » والعزوف عن الشهوات . وعلى « ويش » رعى السائمة والقيام بخدمتها وتلاوة « ويد » والتجارة والزراعة . وليس « لشودر » إلا خدمة هذه الطبقات الثلاث !", "« وقد منح هذا القانون طبقة البراهمة امتيازات وحقوقا ألحقتهم", "(١) الكتاب المقدس ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0061.png"}, {"n": 62, "paras": ["بالآلهة . فقد قال : إن البراهمة هم صفوة الله ، وهم ملوك الخلق ، وإن ما فى العالم هو ملك لهم ، فإنهم أفضل الخلائق وسادة الأرض ، ولهم أن يأخذوا من مال عبيدهم شودر من غير جريرة ما شاءوا . لأن العبد لا يملك شيئا ، وكل ماله لسيده . وأن البرهمى الذى يحفظ « رك ويد » ( الكتاب المقدس ) هو رجل مغفور له ، ولو أباد العوالم الثلاثة بذنوبه وأعماله : ولا يجوز للملك حتى فى أشد ساعات الاضطرار والفاقة أن يجبى من البراهمة جباية ، أو يأخذ منهم إتاوة ، ولا يصح لبرهمى فى بلاده أن يموت جوعا ، وإن استحق برهمى القتل ، لم يجز للحاكم إلا أن يحلق رأسه ، أما غيره فيقتل !", "« أما الشترى فإن كانوا فوق الطبقتين ( ويش وشودر ) ولكنهم دون البراهمة بكثير . فيقول : « منو » إن البرهمى الذى هو فى العاشرة من عمره يفوق الشترى الذى ناهز مئة ، كما يفوق الوالد ولده !", "« أما شودر « المنبوذون » فكانوا فى المجتمع الهندى بنص هذا القانون المدنى الدينى أحط من البهائم ، وأذل من الكلاب . فيصرح القانون بأن « من سعادة شودر أن يقوموا بخدمة البراهمة ، وليس لهم أجر أو ثواب بغير ذلك . وليس لهم أن يقتنوا مالا ، أو يدخروا كنزا فإن ذلك يؤذى البراهمة ! وإذا مد أحد من المنبوذين إلى برهمى يدا أو عصا ليبطش به قطعت يده ، وإذا رفسه فى غضب فدعت رجله ؛ وإذا هم أحد من المنبوذين أن يجالس برهميا فعلى الملك أن يكوى إسته ، أو يحرمه وينفيه من البلاد . وأما إذا مسه بيد ، أو سبه ، فيقتلع لسانه . وإذا ادعى أنه يعلمه سقى زيتا فائرا . وكفارة قتل الكلب والقطة والضفدعة"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0062.png"}, {"n": 63, "paras": ["والوزغ والغراب والبومة . ورجل من الطبقة المنبوذة ، سواء ! ! !(1) » . أما الحضارة الرومانية الشهيرة فقامت على أساس الترف ، الذى يوفره ثلاثة أرباع سكانها من العبيد ، للربع الباقى من الأشراف ! وعلى أساس التفرقة فى نصوص القانون بين السادة والعبيد . وبين الطبقات الكريمة والوضيعة : جاء فى مدونة جوستنيان القانونية الشهيرة : « ومن يستهو أرملة مستقيمة أو عذراء ، فعقوبته إن كان من بيئة كريمة مصادرة نصف ماله . وإن كان من بيئة ذميمة فعقوبته الجلد والنفى من الأرض »(2) وبينما كان هذا « الواقع » سائدا فى الأرض كلها ، كان الإسلام يخاطب « الفطرة » من تحت ركام الواقع . الفطرة التى تنكر هذا كله ولا تعرفه . وكانت استجابة الفطرة لنداء الإسلام أقوى من هذا الواقع الثقيل . استمعت الفطرة إلى الله سبحانه يقول للناس جميعا : « ياأيها الناس إنا خلقناكم من ذكر وأنثى ، وجعلناكم شعوبا وقبائل لتعارفوا . إن أكرمكم عند الله أتقاكم » ..", "(1) المصدر السابق .", "(2) ص 317 ترجمة عبد العزيز فهمى ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0063.png"}, {"n": 64, "paras": ["واستمعت إليه سبحانه يقول لقريش خاصة : « ثم أفيضوا من حيث أفاض الناس » ...", "واستمعت إلى رسول الله صلى الله عليه وسلم يقول للناس جميعا : « أيها الناس . إن ربكم واحد . وإن أباكم واحد . كلكم لآدم وآدم من تراب . إن أكرمكم عند الله أتقاكم . وليس لعربى على عجمى ، ولا لعجمى على عربى ، ولا لأحمر على أبيض ولا لأبيض على أحمر فضل إلا بالتقوى » .", "واستمعت إليه يقول لقريش خاصة :", "« يا معشر قريش . اشتروا أنفسكم ، لا أغنى عنكم من الله شيئا . ويا بنى عبد مناف لا أغنى عنكم من الله شيئا . يا عباس بن عبد المطلب ، ما أغنى عنك من الله شيئا . يا فاطمة بنت محمد : سلينى ما شئت من مالى ، لا أغنى عنك من الله شيئا » .", "استمعت الفطرة إلى النداء المستجاب ؛ وأزاحت عنها ركام « الواقع » وانطلقت مع المنهج الإلهى .. ووقع ما وقع وفق سنة الله المطردة ، القابلة للوقوع فى كل حين .", "وكان النظام الربوى هو السائد فى الجزيرة العربية ، وعليه يقوم اقتصادها الأساسى . ولا يحسبن أحد أنها كانت مجرد معاملات فردية فى"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0064.png"}, {"n": 65, "paras": ["حدود ضيقة . فقد قامت لقريش تجارة ضخمة مع الشام في رحلة الصيف ، ومع اليمن فى رحلة الشتاء . وكانت توظف في هذه التجارة رؤوس أموال قريش . ولا يجوز أن ننسى أن قافلة أبى سفيان التي ترصد لها المسلمون فى غزوة بدر ، ثم أفلتت منهم ، وقسم الله لهم ما هو خير منها ، كانت تحوى ألف بعير موسوقة بالبضائع ! ولو كان الربا مجرد معاملات فردية محدودة ، لا نظاما شاملا للحياة الاقتصادية ما استحق من الله سبحانه هذه الحملة المفزعة المتكررة فى القرآن ، ولا متابعة تلك الحملة من الرسول صلى الله عليه وسلم فى حديثه !", "هذه الأموال ، وهذه الحركة التجارية ، وهذا الاقتصاد الذي يقوم عليها ، كان يقوم كله على أساس النظام الربوى . وفيه تجمعت اقتصاديات البلاد تقريبا قبيل البعثة . فكذلك كانت تقوم الحياة في المدينة . وأصحاب اقتصادها هم اليهود . والربا قاعدة اقتصاد اليهود !", "وكان هذا « واقعا » اقتصاديا تقوم عليه حياة البلاد !", "ثم جاء الإسلام .. جاء ينكر هذا الأساس الظالم الجارم ؛ ويعرض بدله أساسا آخر : أساس الزكاة والقرض الحسن والتعاون والتكافل .", "« الذين ينفقون أموالهم بالليل والنهار سرا وعلانية ، فلهم أجرهم عند ربهم ، ولا خوف عليهم ، ولا هم يحزنون . الذين يأكلون الربا لا يقومون إلا كما يقوم الذى يتخبطه الشيطان من المس . ذلك بأنهم قالوا : إنما البيع مثل الربا . وأحل الله البيع وحرم الربا . فمن جاءه موعظة من ربه فانتهى فله ما سلف ، وأمره إلى الله . ومن عاد فأولئك أصحاب"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0065.png"}, {"n": 66, "paras": ["النار هم فيها خالدون . يمحق الله الربا ويربى الصدقات . والله لا يحب كل كفار أثيم . إن الذين آمنوا وعملوا الصالحات ، وأقاموا الصلاة وآتوا الزكاة ، لهم أجرهم عند ربهم ، ولا خوف عليهم ولا هم يحزنون . ياأيها الذين آمنوا اتقوا الله وذروا ما بقى من الربا إن كنتم مؤمنين . فإن لم تفعلوا فأذنوا بحرب من الله ورسوله ، وإن تبتم فلكم رؤوس أموالكم ، لا تظلمون ولا تظلمون ، وإن كان ذو عسرة فنظرة إلى ميسرة ، وأن تصدقوا خير لكم إن كنتم تعلمون . واتقوا يوما ترجعون فيه إلى الله ثم توفى كل نفس ما كسبت وهم لا يظلمون » .", "ووجدت الفطرة أن دعوة الله خير مما هي فيه . واشمأزت من الأساس الهابط الذى يقوم النظام الربوى عليه . ومع مشقة الانتقال فى الأوضاع الاقتصادية التى تقوم عليها حياة الناس ، فقد كانت استجابة الفطرة أقوى من ثقل « الواقع » ،. وتطهر المجتمع المسلم من تلك اللوثة الجاهلية . وكان ما كان . وفق سنة الله التى تتكرر كلما دعيت الفطرة فانتفضت من تحت الركام والأنقاض !", "ونكتفى فى هذا الفصل بهذه الأمثلة الثلاثة من مغالبة الفطرة للواقع ، وانتفاضها من تحت الركام والأنقاض ؛ وانتصارها على الواقع الخارجي الذى أنشأته الجاهليات .. وهى تمثل واقع العقيدة والتصور . وواقع الأوضاع والتقاليد . وواقع الاقتصاد والتعامل .. وهى أقوى ألوان"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0066.png"}, {"n": 67, "paras": ["« الواقع » الذي يراه من لا يدركون قوة العقيدة ، وقوة الفطرة ، وكأنه هو الحقيقة الساحقة التي لا قبل بها لفطرة ولا عقيدة !", "إن الإسلام لم يقف مستسلما عاجزا مكتوف اليدين أمام هذا « الواقع » . ولكنه ألغاه ، أو بدله ، وأقام مكانه بناءه السامق الفريد ، على أساسه القوى العميق .", "وما حدث مرة يمكن أن يحدث مرة أخرى . فقد حدث ما حدث وفق سنة جارية ، لا وفق معجزة خارقة . وقد قام ذلك البناء على رصيد الفطرة المدخر لكل من يستنقذ هذا الرصيد ، ويجمعه ، ويوجهه ، ويطلقه في اتجاهه الصحيح .", "والبشرية اليوم قد تكون أقدر على هذا الاتجاه الصحيح . بما استقر في تاريخها وفى حياتها من آثار ذلك المد الأول ؛ الذي واجه أقسى المعارضة ، ثم انساح في طريقه ؛ وخلف من بعده أعمق الآثار .."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0067.png"}, {"n": 68, "paras": ["رَصِيدُ التَّجْرِبَة", "عندما واجه الإسلام البشرية أول مرة كان يواجه هذا الواقع برصيد الفطرة وحده . كان رصيد الفطرة مع هذا الدين ؛ على الرغم من الأجيال الطويلة التي انقضت وهي تراكم فوقه أنقاض الواقع الجاهلي العريض .. ولكن انتفاض الفطرة كان أقوى من كل ذلك الركام ؛ وكانت استجابة الفطرة كافية لفض ذلك الركام .", "وكانت تلك الفترة العجيبة . وكانت تلك القمة السامقة . وكان ذلك الجيل الفارع . وكانت تلك المنارة الوضيئة .. كانت كما قلنا قدرا من أقدار الله ، وتدبيرا من تدبيره ، لتتجسم هذه الصورة الفريدة ، في أوضاع حياة واقعية ، يمكن فيما بعد الرجوع إليها في صورتها الواقعية ، ومحاولة تكرارها على مدى الزمن ، بقدر ما تتهيأ لها البشرية !", "إنها لم تكن ثمرة طبيعية لبيئتها - وقتذاك - ولكنها كانت ثمرة الرصيد المتجمع للفطرة ؛ عندما وجدت المنهج والقيادة والتربية والحركة التي تجمع هذا الر"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0068.png"}, {"n": 69, "paras": ["التي لم يعرف لها التاريخ نظيرا ، ودخل الناس في دين الله أفواجا ، وأصبحت كثرة الأمة الإسلامية ليست هي التي تلقت تلك التربية الفريدة العميقة البطيئة التي تلقتها الجماعة المختارة ..", "لما وقع هذا كله أخذ ضغط الرواسب الجاهلية في نفوس الجماهير الغفيرة ، والكثرة الكاثرة في جموع الأمة التي دانت للإسلام « يثقل » ويجذب الجسم كله من تلك القمة السامقة ، إلى الأرض المستوية ! الجسم الذي لا يرفعه إلى تلك القمة السامقة إلا الوثبة الكبرى ، التي وثبتها تلك الجماعة المختارة ، بدفعة التربية الفريدة العميقة البطيئة ، التي جمعت رصيد الفطرة وأطلقته في هذا الاتجاه البعيد !", "ومن ثم استوى المجتمع المسلم قرابة ألف عام لا على تلك القمة السامقة ؛ ولكن في مستويات متفاوتة ، كلها أرفع من مستويات المجتمعات الأخرى في أرجاء الأرض ، وذلك مع استمداد تلك المجتمعات من ذلك المجتمع الرفيع ؛ كما شهد التاريخ المنصف . وما أقل التاريخ المنصف !", "تلك الوثبة الكبرى الفريدة في تاريخ البشرية ؛ وهذه الألف عام من المستويات الرفيعة .. لم تذهب كلها سدى ، ولم تتبدد من عالم الحياة ضياعا ، ولم تترك البشرية بعدها كما تسلمتها من قبل .", "كلا ! فليس ذلك من سنة الله في الحياة والناس . فالبشرية وحدة متماسكة على مدار الزمان ، وجسم البشرية جسم حي ؛ ينتفع بزاد"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0069.png"}, {"n": 70, "paras": ["التجارب ، ويدخر رصيد المعرفة . ومهما تجمع فوقه ركام الجاهلية التى ارتدت إليها البشرية ؛ ومهما ران عليها العمى والظلام ؛ فإن الرصيد باق مكنون ، بل هو سار فى الجسم على العموم !", "وإذا كانت الدعوة إلى الإسلام فى المرة الأولى ، لم تجد إلا رصيد الفطرة تواجه به واقع البشرية (وذلك دون أن نغفل الرصيد الضئيل المتبقى كالذبالة من بقايا الرسالات الأولى التى كانت رسالات فى أقوام ، ولم تكن للبشر كافة كالإسلام) فإنها اليوم تجد إلى جانب رصيد الفطرة المكنون ، رصيد الموجة الأولى لهذا المنهج الإلهى فى حياة البشرية جمعاء من آمن بالإسلام ، ومن دخل فى حكم الإسلام ، ومن تأثر على البعد بالمد الإسلامى العريض كما تجد رصيد التجارب البشرية المريرة ، التى عانتها فى التيه ، حين بعدت عن الله ، وعانت فى ذلك التيه مرارة الحياة !", "والمبادئ والتصورات ، والقيم والموازين ، والنظم والأوضاع ، التى واجه بها الإسلام البشرية أول مرة وليس معه إلا رصيد الفطرة فأنكرتها أشد الإنكار ؛ وتنكرت لها كل التنكر ؛ وقاومتها كل المقاومة ؛ لأنها يومذاك كانت غريبة كل الغرابة ؛ وكانت المسافة بينها وبين واقعها سحيقة هائلة ...", "هذه المبادئ والتصورات ، والقيم والموازين ، والأنظمة والأوضاع ، قد استقرت فى حياة جماعة من البشر وهى فى صورتها الكاملة فترة من الزمان . ثم استقرت فى حياة العالم الإسلامى العريض فى مستويات متفاوتة فترة طويلة أخرى . ثم عرفت فى حياة"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0070.png"}, {"n": 71, "paras": ["الجماعة البشرية كلها تقريبا ، خلال نيف وثلاثمئة وألف عام .. عرفت على الأقل دراسة ورؤية وفرجة ! إن لم تعرف مزاولة وعملا وتجربة ! ومن ثم لم تعد غريبة على البشرية كما كانت يوم جاءها بها الإسلام أول مرة . ولم تعد منكرة فى حسها وعرفها كما كانت يومذاك !", "حقيقة إن البشرية لم تتذوقها قط ، كما تذوقتها الجماعة المختارة ، وفى تلك الفترة الفريدة . وحقيقة إنها حين حاولت تطبيق بعضها فى أزمنة متفاوتة بما فى ذلك العصر الحديث لم تدرك روحها قط ، ولم تطبقها بهذه الروح . وحقيقة إنها حتى اللحظة ما تزال تطلع وهى تدرج فى المرتقى الذى وثبت إليه الجماعة المسلمة الأولى ..", "كل هذا صحيح . ولكن البشرية بجملتها من الناحية التصورية الفكرية قد تكون أقرب إلى إدراك طبيعة ذلك المنهج ، وأقدر على حمله كذلك منها يوم جاءها أول مرة ، غريبا عليها كل الغرابة .", "والأمثلة المحددة تقرب هذه الحقيقة وتوضحها . ونحن نكتفى بذكر القليل منها دون الإحاطة بها . وذلك لاعتبارين هامين :", "أولهما : طبيعة هذا البحث المجمل المختصر ؛ الذى لا يزيد على أن يكون مجرد إشارات دالة إلى عناصر الموضوع الكبير الذى يتناوله موضوع «هذا الدين» .", "وثانيهما : أن الخطوط العريضة التى تركتها موجة المد الطويلة لهذا"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0071.png"}, {"n": 72, "paras": ["المنهج ، فى حياة البشرية كلها ، وفى أنحاء الأرض جميعاً ، أكثر عدداً ، وأضخم أثرا ، وأوسع مساحة ، من أن يحيط بها كاتب واحد ، فى بحث واحد ، وفى عصر واحد . فهذه الآثار قد ترسبت فى حياة البشرية كلها ، منذ ذلك العهد البعيد ؛ وشملت حياة البشرية كلها على نطاق واسع ؛ وتأثرت به جوانب قد لا تكون كلها ظاهرة ، وقد لا تكون كلها مما سجلته الملاحظة .", "وإنه ليمكن القول على وجه الإجمال أن هذه الظاهرة الكونية ، التى تجلت على هذا الكوكب الأرضى ، وتمت فى حياة هذه البشرية .. وهى ظاهرة هذا الدين .. لم تدع جانبا واحدا من حياة البشرية منذ ذلك التاريخ ، إلا وتجلت فيه وتركت فيه تأثيرا تفاوت درجاته ، ولكنه واقع لا شك فيه . وإن كل حركة من حركات التاريخ الكبرى قد استمدت مباشرة أو غير مباشرة من ذلك الحدث الكبير ؛ أو بتعبير أصح من هذه الظاهرة الكونية الضخمة .", "إن حركة الإصلاح الدينى ، التى قام بها مارتن لوثر وكالفن فى أوربا . وحركة الإحياء التى تقتات منها أوربا حتى اليوم وحركة تحطيم النظام الإقطاعى فى أوربا ، والانطلاق من حكم الأشراف . وحركة المساواة وإعلان حقوق الإنسان التى تجلت فى الماجنا كارتا فى انجلترا والثورة الفرنسية فى فرنسا . وحركة المذهب التجريبى التى قام عليها مجد أوربا العلمى ، وانبعثت منها الفتوحات العلمية الهائلة فى العصر"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0072.png"}, {"n": 73, "paras": ["الحديث .. وأمثالها من الحركات الكبرى ، التى يحسبها الناس أصولا فى التطور التاريخى .. كلها قد استمدت من ذلك المد الإسلامى الكبير ، وتأثرت به تأثرا أساسيا عميقا ..", "جاء فى كتاب «ضحى الإسلام» للدكتور أحمد أمين :", "«ظهر بين النصارى نزعات يظهر فيها أثر الإسلام من ذلك أنه فى القرن الثامن الميلادى أى فى القرنين الثانى والثالث الهجريين ظهرت فى سبتمانيا (Septmania)^{(۱)} حركة تدعو إلى إنكار الاعتراف أمام القسس وأن ليس للقسس حق فى ذلك ؛ وأن يضرع الإنسان إلى الله وحده فى غفران ما ارتكب من إثم . والإسلام ليس له قسيسون ورهبان وأحبار . فطبيعى ألا يكون فيه اعتراف !", "وكذلك قامت حركة تدعو إلى تحطيم الصور والتماثيل الدينية (Iconoclasts) . ذلك أنه فى القرن الثامن والتاسع للميلاد أى فى القرن الثالث والرابع الهجرى ظهر مذهب نصرانى يرفض تقديس الصور والتماثيل . فقد أصدر الإمبراطور الرومانى «ليو» الثالث أمرا سنة", "٧٢٦م يحرم فيه تقديس الصور والتماثيل ، وأمرا آخر فى سنة ٧٣٠ يعد الإتيان بهذا وثنية . وكذلك كان قسطنطين الخامس وليو الرابع . على حين كان البابا «جريجورى الثانى والثالث» و «جرمانيوس» بطريرك القسطنطينية ، والإمبراطورة «إيرينى» من مؤيدى عبادة الصور . وجرى بين الطائفتين نزاع شديد ، لا محل لتفصيله . وكل ما نريد أن نذكره أن", "(۱) سبتمانيا مقاطعة فرنسية قديمة فى الجنوب الغربى لفرنسا على البحر الأبيض المتوسط ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0073.png"}, {"n": 74, "paras": ["بعض المؤرخين يذكرون أن الدعوة إلى نبذ الصور والتماثيل كانت متأثرة بالإسلام. ويقولون إن كلوديوس ( Cloudius ) أسقف تورين (الذى عين سنة ٨٢٨م وحول ٢١٣ه) والذى كان يحرق الصور والصلبان ، وينهى عن عبادتها في أسقفيته ولد وربي في الأندلس الإسلامية .", "... «كذلك وجدت طائفة من النصارى ،. شرحت عقيدة التثليث بما يقرب من الوحدانية ، وأنكرت ألوهية المسيح (١) .", "وحينما عادت جيوش الصليبيين المتبربرة مرتدة عن الشرق الإسلامي في القرن الحادي عشر الميلادى ، عادت ومعها صورة من حياة المجتمع الإسلامي . وعلى كل ما كان قد وقع من الانحرافات فى هذا المجتمع ، فإن الظاهرة البارزة فيه بالقياس إلى ذلك القطيع الصليبي المتبربر كانت ظاهرة الشريعة الواحدة ، التى يخضع لها الحاكم والمحكوم ؛ والتي لا تستمد من إرادة الشريف أو هوى صاحب الإقطاعية كما كان الحال فى أوربا ؛ وظاهرة الحرية الشخصية فى اختيار نوع العمل ومكان الإقامة ؛ وظاهرة الملكية الفردية وحرية الاستثمار ؛ وظاهرة انعدام الطبقية الوراثية واستطاعة كل فرد فى أى وقت أن يرتفع بدرجته في المجتمع وفق جده واجتهاده وعمله . هذه الظواهر البارزة ، التي لا تخطئها عين الأوربي", "(۱) ضحى الإسلام ص ١٦٤ ١٦٥"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0074.png"}, {"n": 75, "paras": ["الذى كان يعيش فى نظام الإقطاع ، رقيقا للأرض ، قانونه هو إرادة السيد ، وطبقته حتمية لأن «الشرف» وراثى !", "ومن هنا بمساعدة العوامل الاقتصادية الأخرى فى حياة المجتمع الأوربى انطلقت الصيحات التى حطمت النظام الإقطاعى تدريجيا ؛ وأعلنت تحرير الأفراد من رق الأرض . وإن لم تحررهم من سائر القيود الأخرى . ولم ترفع مجتمعهم إلى مستوى المجتمع الإسلامى !", "ومن جامعات الأندلس ، ومن تأثير حضارة الشرق الإسلامى ، التى أصبحت حضارة عالمية ؛ ومن الترجمات الأوربية لتراث العالم الإسلامى انبثقت حركة الإحياء الأوربية فى القرن الرابع عشر وما تلاه . وانبثقت كذلك الحركة العلمية الحديثة ، وبخاصة الطريقة التجريبية :", "يقول «بريفولت» مؤلف كتاب : «بناء الإنسانية» :", "«لقد كان العلم أهم ما جاءت به الحضارة العربية(١) على العالم الحديث ، ولكن ثماره كانت بطيئة النضج .. إن العبقرية التى ولدتها", "(١) يلاحظ أن الكتاب الغربيين يحرصون على تسمية الحضارة الإسلامية باسم الحضارة العربية . وذلك عن خبث ومكر منهم . فكلمة إسلامية . ثقيلة على قلوبهم . وهم بهذا يريدون حصر الإسلامية فى العربية . والإسلامية أوسع من هذا النطاق الضيق الصغير. وهم يريدون كذلك إحياء العنصرية البغيضة بين الجماعات الإسلامية ، التى أماتها الإسلام . وكلها أغراض ماكرة خبيثة ! ! !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0075.png"}, {"n": 76, "paras": ["ثقافة العرب فى أسبانيا ، لم تنهض فى عنفوانها إلا بعد وقت طويل على اختفاء تلك الحضارة وراء سحب الظلام ، ولم يكن العلم وحده هو الذى أعاد إلى أوربا الحياة . بل إن مؤثرات أخرى كثيرة من مؤثرات الحضارة الإسلامية بعثت باكورة أشعتها إلى الحياة الأوربية . فإنه على الرغم من أنه ليس ثمة ناحية واحدة من نواحى الازدهار الأوربى إلا ويمكن إرجاع أصلها إلى مؤثرات الثقافة الإسلامية بصورة قاطعة ، فإن هذه المؤثرات توجد أوضح ما تكون ، وأهم ما تكون ، فى نشأة تلك الطاقة ، التى تكوّن ما للعالم الحديث من قوة متمايزة ثابتة ، وفى المصدر القوى لازدهاره : أى فى العلوم الطبيعية ، وروح البحث العلمى » .", "ويستطرد فيقول :", "« إن ما يدين به علمنا لعلم العرب ليس فيما قدموه إلينا من كشوف مدهشة لنظريات مبتكرة ؛ بل يدين هذا العلم إلى الثقافة العربية بأكثر من هذا : إنه يدين لها بوجوده نفسه . فالعالم القديم كما رأينا لم يكن للعلم فيه وجود ، وعلم النجوم عند اليونان ورياضياتهم كانت علوما أجنبية ، استجلبوها من خارج بلادهم ؛ وأخذوها عن سواهم ؛ ولم تتأقلم فى يوم من الأيام ، فتمتزج امتزاجا كليا بالثقافة اليونانية . وقد نظم اليونان المذاهب ، وعمموا الأحكام ، ووضعوا النظريات . ولكن أساليب البحث فى دأب وأناة ، وجمع المعلومات الإيجابية وتركيزها ، والمناهج التفصيلية للعلم ، والملاحظة الدقيقة المستمرة ، والبحث التجريبى .. كل ذلك كان غريبا تماما عن المزاج اليونانى . أما ما ندعو « العلم » فقد ظهر فى أوربا نتيجة لروح من البحث جديدة ، ولطرق من"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0076.png"}, {"n": 77, "paras": ["الاستقصاء مستحدثة . من طرق التجربة والملاحظة والمقاييس ، ولتطور الرياضيات إلى صورة لم يعرفها اليونان .. وهذه الروح ، وتلك المناهج العلمية أدخلها العرب إلى العالم الأوربى » (١) .", "وقبل ذلك يقول :", "« وإن « ردجر بيكون » درس اللغة العربية والعلم العربى فى مدرسة « أكسفورد » على خلفاء معلميه العرب فى الأندلس . وليس ل « ردجر بيكون » ، ولا لسميه « فرنسيس بيكون » الذى جاء بعده الحق فى أن ينسب إليهما الفضل فى ابتكار المنهج التجريبى . فلم يكن ردجر بيكون ، إلا رسولا من رسل العلم والمنهج الإسلاميين إلى أوربا المسيحية . وهو لم يمل قط من التصريح بأن تعلم معاصريه للغة العربية وعلوم العرب هو الطريق الوحيد للمعرفة الحقة . والمناقشات التى دارت حول واضعى المنهج التجريبى هى طرف من التحريف الهائل لأصول الحضارة الأوربية . وقد كان منهج العرب فى عصر « بيكون » قد انتشر انتشارا واسعا ، وانكب الناس فى لهف على تحصيله فى ربوع أوربا .", "« من أين استقى « ردجر بيكون » ما حصله من العلوم ؟", "« من الجامعات الإسلامية فى الأندلس . والقسم الخامس من كتابه ( Cepus Majus ) الذى خصصه للبحث فى البصريات ، هو فى", "(١) عن كتاب « تجديد التفكير الدينى فى الإسلام » تأليف الفيلسوف محمد إقبال . وترجمة الأستاذ عباس محمود ص ١٤٩ - ١٥٠ ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0077.png"}, {"n": 78, "paras": ["حقيقة الأمر نسخة من كتاب «المناظر لابن الهيثم»(١) .", "ويقول دريبر الأستاذ بجامعة نيويورك فى كتابه : «النزاع بين العلم والدين» :", "«تحقق علماء المسلمين من أن الأسلوب العقلى النظرى لا يؤدى إلى التقدم ؛ وأن الأمل فى وجدان الحقيقة يجب أن يكون معقودا بمشاهدة الحوادث ذاتها . ومن هنا كان شعارهم فى أبحاثهم ، الأسلوب التجريبى ، والدستور العملى الحسى .", "«إن نتائج هذه الحركة العملية تظهر جلية فى التقدم الباهر الذى نالته الصنائع فى عصرهم ، وإننا لندهش حين نرى فى مؤلفاتهم من الآراء العلمية ، ما كنا نظنه من نتائج العلم فى هذا العصر . ومن ذلك أن مذهب النشوء والارتقاء للكائنات العضوية الذى يعتبر مذهبا حديثا كان يدرس فى مدارسهم . وقد ذهبوا فيه إلى أبعد مما وصلنا إليه . وذلك بتطبيقه على الجوامد والمعادن(٢) .. وقد استخدموا علم الكيمياء فى", "(١) المصدر السابق ص ١٤٨ من الترجمة العربية .", "(٢) يجب الاحتراس من مثل هذا القول ، الذى يلقيه المؤلفون الغربيون ، فى معرض إنصافهم للإسلام والتفكير الإسلامى . فمذهب النشوء والارتقاء كما قرره دارون وولاس ، شئ آخر غير ما قرره المسلمون فى بحثهم العلمى المؤمن البرىء من لوثة الهروب من الكنيسة ومن إله الكنيسة فى العالم الغربى ! وقد لاحظ علماء المسلمين التدرج بين مراتب الخلائق . وبدأوا من صفات المادة الجامدة ورأوا أنها تنتهى عند أول مراتب الحياة النباتية ورأوا أن هذه تنتهى عند أول مراتب الحياة الحيوانية . ثم تترقى هذه الحياة . ولكنهم ردوا كل ذلك إلى تقدير الله وفاعلية الله . أما دارون فقد ="], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0078.png"}, {"n": 79, "paras": ["الطب ، ووصلوا فى علم الميكانيكا إلى أنهم عرفوا وحددوا قوانين سقوط الأجسام وكانوا عارفين كل المعرفة بعلم الحركة ؛ ووصلوا في نظريات الضوء والإبصار إلى أن غيروا الرأى اليونانى القائل بأن الإبصار يحصل بوصول شعاع من البصر إلى الجسم المرئى ، وقالوا بالعكس . وكانوا يعرفون نظريات انعكاس الأشعة وانكسارها . وقد اكتشف الحسن ابن الهيثم الشكل المنحنى الذى يأخذه الشعاع في سيره في الجو ؛ وأثبت بذلك أننا نرى القمر والشمس قبل أن يظهرا حقيقة في الأفق ؛ وكذلك نراهما في المغرب بعد أن يغيبا بقليل » (١) .", "ونكتفى بهذا القدر من الآثار الواقعية للمنهج الإسلامي وللحياة الإسلامية ، فى تاريخ البشرية ، وفى الحركات العالمية الكبرى . نكتفى", "= حرص على نفي تدخل أى عنصر غيبي فى النشوء والارتقاء . لأنه كان هارباً من الكنيسة ومن إله الكنيسة الذى باسمه تضطهد العلم والبحث العلمى على الإطلاق .. كذلك لم تتطرق إلى بحوث علماء المسلمين لوثة تحقير الإنسان وتجريده من كل عنصر روحى ورده إلى أصل حيوانى . فالنظرية الإسلامية صريحة فى أن الإنسان خلق مستقل . وإن كان يجلس على قمة مراتب الكائنات الحية من حيث تكوينه العضوى واستعداده العقلى والروحى . ولكنه كان هكذا لأن الله سبحانه أنشأه ابتداء كما أنشأ سائر الخلائق فى مراتبها التى وجدت عليها .. فهناك فارق كبير فى أصل النظرة مع سبق المسلمين فى البحث العلمى .", "(١) عن كتاب : الإسلام دين عام خالد للأستاذ محمد فريد وجدى ص ٢٣٣ طبعة ثانية ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0079.png"}, {"n": 80, "paras": ["بهذا القدر بوصفه مجرد إشارة إلى هذه الحقيقة. الضخمة الممتدة الأطراف التى كثيرا ما ننساها ، ونحن نشهد البناء الحضارى الراهن ؛ ويخيل إلينا فى سذاجة وغفلة أنه لا نصيب لنا فيه ، ولا أثر لنا فى نشأته ؛ وأنه شىء أضخم منا ومن تاريخنا الذى نجهله مع الأسف الشديد ؛ ثم نتلقاه من أفواه أعدائنا ؛ الذين لا هم لهم إلا أن يملأوا قلوبنا باليأس من إمكان الحياة الإسلامية ، وفق المنهج الإسلامى . وهم أصحاب مصلحة فى هذا اليأس ؛ لأنه يؤمنهم من الكرة عليهم ، ومن استرداد زمام القيادة العالمية منهم .. فما بالنا نحن ياترى نتلقف ما يقولونه ، ونردده كالببغاوات والقرود ؟", "وعلى أى فهذا ليس موضوعنا هنا . إنما نحن نمهد بهذه الإشارة إلى إشارة أخرى نحو الخطوط العريضة التى خطها المد الإسلامى الأول ؛ وعرفها للبشرية ؛ فأصبحت البشرية اليوم أقدر على إدراكها وتصورها . وهى الرصيد الجديد الذى يضاف إلى رصيد الفطرة القديم !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0080.png"}, {"n": 81, "paras": ["خُطُوط مُسْتَقِرّة", "عندما انحسرت موجة المد الإسلامي العالية عن هذه الأرض ؛ وحينما استردت الجاهلية زمام القيادة ، التي كان الإسلام قد انتزعها منها ، وعندما عاد الشيطان ينفض غبار المعركة عن كاهله ، وينهض من عثرته ، ويهتف لحزبه الذى عاد يتسلم الزمام !", "عندما حدث هذا كله لم ترتد حياة البشرية تماما إلى أوضاعها المتخلفة فى الجاهلية الأولى .. لقد كان الإسلام هناك حتى وهو يتراجع عن مكان الصدارة فى الأرض وكانت هنالك من ورائه خطوط عريضة ، ومبادىء ضخمة ، قد استقرت فى حياة البشرية ، وصارت مألوفة للناس ، وزالت عنها الغرابة التى استقبلوها بها يوم جاءهم بها الإسلام أول مرة .", "هذه الخطوط العريضة ، وهذه المبادىء الضخمة هى التى سنحاول الإشارة إلى نماذج قليلة منها فى هذا الفصل على سبيل الإجمال .", "إنسانية واحدة : من العصبية القبلية ، بل عصبية العشيرة ، بل عصبية البيت ، التى"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0081.png"}, {"n": 82, "paras": ["كانت تسود الجزيرة العربية .. ومن عصبية البلد ؛ وعصبية الوطن ؛ وعصبية اللون ؛ وعصبية الجنس .. التي كانت تسود وجه الأرض كله ..", "من هذه العصبيات الصغيرة التى لم تكن البشرية تتصور غيرها فى ذلك الزمان ، جاء الإسلام ليقول للناس : إن هناك إنسانية واحدة ، ترجع إلى أصل واحد ، وتتجه إلى إله واحد . وإن اختلاف الأجناس والألوان ، واختلاف الرقعة والمكان ، واختلاف العشائر والآباء ... كل أولئك لم يكن ، ليتفرق الناس ويختصموا ، ويتحوصلوا وينعزلوا . ولكن ليتعارفوا ويتآلفوا ؛ وتتوزع بينهم وظائف الخلافة في الأرض ؛ ويرجعوا بعد ذلك إلى الله الذى ذرأهم في الأرض واستخلفهم فيها . وقال لهم الله سبحانه في القرآن الكريم :", "«يا أيها الناس إنا خلقناكم من ذكر وأنثى ، وجعلناكم شعوبا وقبائل لتعارفوا . إن أكرمكم عند الله أتقاكم . إن الله عليم خبير» ... (الحجرات : ١٣)", "«ياأيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة ، وخلق منها زوجها ، وبث منهما رجالا كثيرا ونساء . واتقوا الله الذي تساءلون به والأرحام . إن الله كان عليكم رقيبا» ... (النساء : ١)", "«ومن آياته خلق السماوات والأرض واختلاف ألسنتكم وألوانكم ، إن في ذلك لآيات للعالمين» ... (الروم : ٢٢)"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0082.png"}, {"n": 83, "paras": ["ولم تكن هذه مبادىء نظرية ؛ ولكنها كانت أوضاعا عملية .. لقد انساح الإسلام فى رقعة من الأرض فسيحة ؛ تكاد تضم جميع الأجناس وجميع الألوان .. وذابت كلها فى النظام الإسلامى . ولم تقف وراثة لون ، ولا وراثة جنس ، ولا وراثة طبقة ، ولا وراثة بيت ، دون أن يعيش الجميع إخوانا ؛ ودون أن يبلغ كل فرد منهم ما تؤهله له استعداداته الشخصية . وما تكفله له صفته الإنسانية .", "واستقر هذا الخط العريض فى الأرض ؛ بعد أن كان غريبا فيها أشد الغرابة ، ومستنكرا فيها كل الاستنكار .. وحتى بعد انحسار المد الإسلامى لم تستطع البشرية أن تتنكر له كل التنكر ؛ ولم تعد تستغربه كل الاستغراب ..", "حقيقة : إنها لم تستطع أن تتمثله كما تمثلته الجماعة المسلمة ؛ ولم يستقر فيها استقراره فى المجتمع الإسلامى .", "وحقيقة : إن عصبيات شتى صغيرة ما تزال تعيش . عصبيات الأرض والوطن . وعصبيات الجنس والقوم . وعصبيات اللون واللسان .", "وحقيقة : إن الملونين فى أمريكا وجنوب إفريقيا يؤلفون مشكلة حادة بارزة ، كما يؤلفون مشكلة ناعمة مستترة فى أوربا كلها !", "ولكن فكرة الإنسانية الواحدة ما تزال خطا عريضا فى هتافات البشرية اليوم ، وما يزال هذا الخط الذى خطه الإسلام هو أصل التفكير البشرى من الناحية النظرية وما تزال تلك العصبيات الصغيرة تبزغ وتختفى ؛ لأنها ليست أصيلة ولا قويمة !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0083.png"}, {"n": 84, "paras": ["لقد انحسر المد الإسلامى الأول ، الذى استمد من رصيد الفطرة وحده ما خط به هذا الخط العريض . ولكنه ترك للمد التالى رصيد الفطرة ورصيده الذاتى . لتستمد منه الجولة القادمة . والبشرية أكثر إدراكاً ، وأكثر استعداداً ، وقد زالت عنها دهشة المفاجأة بهذا الخط الجديد ! ! !", "انسانية كريمة :", "وجاء الإسلام والكرامة الإنسانية وقف على طبقات معينة ، وعلى بيوت خاصة ، وعلى مقامات معروفة .. أما الغثاء . غثاء الجماهير. فهو غثاء ! لا وزن له ولا قيمة ، ولا كرامة ! غثاء ! ! !", "وقال الإسلام كلمته المدوية : إن كرامة الإنسان مستمدة من « إنسانيته » ذاتها لا من أى عرض آخر كالجنس ، أو اللون ، أو الطبقة ، أو الثروة ، أو المنصب ... إلى آخر هذه الأعراض العارضة الزائلة .. والحقوق الأصيلة للإنسان مستمدة إذن من تلك الإنسانية . التى ترجع إلى أصل واحد كما أسلفنا .", "وقال لهم الله فى القرآن الكريم :", "« ولقد كرمنا بنى آدم ، وحملناهم فى البر والبحر ، ورزقناهم من الطيبات ، وفضلناهم على كثير ممن خلقنا تفضيلا »", "( الإسراء : ٧٠ )"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0084.png"}, {"n": 85, "paras": ["« وإذ قال ربك للملائكة : إنى جاعل فى الأرض خليفة » ( البقرة : ٣٠ )", "« وإذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس أبى واستكبر وكان من الكافرين » ( البقرة : ٣٤ )", "« وسخر لكم ما فى السماوات وما فى الأرض جميعاً منه » . ( الجاثية : ١٣ )", "وعلم الناس منذئذ : أن الإنسان بجنسه كريم على الله . وأن كرامته ذاتية أصيلة ؛ لا تتبع جنسه ، ولا لونه ، ولا بلده ، ولا قومه ، ولا عشيرته ، ولا بيته . ولا عرضا من هذه الأعراض الزائلة الرخيصة . إنما تتبع كونه إنسانا من هذا الجنس الذى أفاض عليه ربه التكريم .", "ولم تكن هذه مبادىء نظرية ، إنما كانت واقعا عمليا ، تمثل فى حياة الجماعة المسلمة ، وانساحت به فى أرجاء الأرض ، فعلمته للناس ، وأقرته فى أوضاع حياتهم كذلك . وعلمت جمهور الناس .. ذلك الغثاء .. أنه كريم ، وأن له حقوقا ، هى حقوق الإنسان ، وأن له أن يحاسب حكامه وأمراءه ، وأن عليه ألا يقبل الذل والضيم والمهانة . وعلمت الحكام والأمراء ألا تكون لهم حقوق زائدة على حقوق الجماهير من الناس ، وأنه ليس لهم أن يهينوا كرامة أحد ممن ليس بحاكم ولا أمير ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0085.png"}, {"n": 86, "paras": ["وكان هذا ميلاداً جديداً «للإنسان» .. ميلادا أعظم من الميلاد الحسى .. فما الإنسان إذا لم تكن له حقوق الإنسان وكرامة الإنسان؟ وإذا لم تكن تلك الحقوق متعلقة بوجوده ذاته وبحقيقته التى لا تتخلف عنه فى حال من الأحوال؟", "بدأ أبو بكر رضى الله عنه عهده بقوله :", "«لقد وليت عليكم ولست بخيركم . فإن أحسنت فأعينونى . وإن أسأت فقومونى . أطيعونى ما أطعت الله ورسوله . فإن عصيته فلا طاعة لى عليكم» ...", "وخطب عمر بن الخطاب رضى الله عنه فقال يعلم الناس حقوقهم تجاه الأمراء :", "«يا أيها الناس . إنى والله ما أرسل إليكم عمالا ليضربوا أبشاركم . ولا ليأخذوا من أموالكم . ولكنى أرسلهم إليكم ليعلموكم دينكم وسنتكم . فمن فعل به شىء من ذلك فليرفعه إلىّ . فوالذى نفس عمر بيده لأقصنه منه .. » فوثب عمرو بن العاص فقال :", "«يا أمير المؤمنين أرأيتك ان كان رجل من أمراء المسلمين على رعيته ، فأدب بعض رعيته . إنك لتقص منه ؟ »", "«قال عمر : إى والذى نفس عمر بيده . إذاً لأقصنه منه . وكيف لا أقص منه . وقد رأيت رسول الله صلى الله عليه وسلم يقص من"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0086.png"}, {"n": 87, "paras": ["نفسه . ألا لا تضربوا الناس فتذلوهم ، ولا تجمّروهم ⁽¹⁾ فتفتنوهم ، ولا تمنعوهم حقوقهم فتكفروهم » .", "وكتب عثمان رضى الله عنه إلى جميع الأمصار كتابا قال فيه : « إنى آخذ عمالى بموافاتى كل موسم وقد سلطت الأمة على الأمر بالمعروف والنهى عن المنكر ؛ فلا يرفع علىّ شيء ولا على أحد من عمالى إلا أعطيته . وليس لى ولا لعمالى حق قبل الرعية لا متروك لهم . وقد رفع إلىّ أهل المدينة أن أقواما يشتمون ويضربون . فمن ادعى شيئاً من ذلك فليواف الموسم ، يأخذ حقه حيث كان ، منى أو من عمالى . أو تصدّقوا ، إن الله يجزى المتصدقين » .", "والمهم كما أسلفنا أن هذه لم تكن مجرد مبادئ نظرية ، أو مجرد كلمات تقال . فقد طبقت تطبيقا واقعياً ؛ وسرت في أوساط الشعوب حتى اتخذت قاعدة للأوضاع العملية .", "وحادثة ابن القبطى الذى سابق ابن عمرو بن العاص ، فاتح مصر وواليها فسبقه فضربه ابن عمرو ، فشكا أبوه إلى عمر بن الخطاب رضى الله عنه فأقصه منه فى موسم الحج وعلى ملأ من الناس .. حادثة معروفة .", "وقد اعتاد الكتاب أن يقفوا فيها عند عدل عمر ... ولكن الحادثة أوسع دلالة على ذلك التيار التحررى الذى أطلقه الإسلام فى ضمائر الناس وفى حياتهم ..", "(۱) لا تجمروهم . لا تبعدوهم طويلا عن بيوتهم وأزواجهم ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0087.png"}, {"n": 88, "paras": ["فمصر إذ ذاك بلد مفتوح . حديث عهد بالفتح وبالإسلام . وهذا القبطى قبطى لم يزل على دينه ، فرداً من جماهير البلد المفتوح . وعمرو بن العاص هو فاتح هذا الإقليم ، وأول أمير عليه من قبل الإسلام .. وحكام هذا الإقليم قبل الفتح الإسلامى هم الرومان : أصحاب السياط التى تجلد ظهور شعوب المستعمرات ! ولعل ذلك القبطى كان ما يزال ظهره يحمل آثار سياط الرومان !", "ولكن المد التحررى الذى أطلقه الإسلام فى أنحاء الأرض ، أنسى ذلك القبطى سياط الرومان وذلها ؛ وأطلقه إنسانا حرا كريما ؛ يغضب لأن يضرب ابن الأمير ابنه ، بعد اشتراكهما فى سباق ، وهذه أخرى ، ثم تحمله هذه الغضبة لكرامة ابنه الجريحة على أن يركب من مصر الى المدينة ، لا طيارة ولا سيارة ولا باخرة ولا قطارا ، ولكن جملا ، يخب به وبضع الأشهر الطوال ، كل ذلك ليشكو إلى الخليفة .. الخليفة الذى حرره يوم فتح بلده تحت راية الإسلام ! والذى علمه الكرامة بعد أن نسيها تحت وقع سياط الرومان !", "وهكذا ينبغى أن نفهم ؛ وأن ندرك عمق المد الإسلامى التحررى فليست المسألة فقط أن عمر عادل ؛ وأن عدله لا تتطاول إليه الأعناق فى جميع الأزمان ، ولكن المسألة بعد ذلك أن عدل عمر المستمد من الإسلام ومنهجه ونظامه قد انطلق فى الأرض تيارا جارفا محررا مكرما للإنسان .. بصفته «الإنسان» ..", "هذا المستوى الرفيع لم ترتفع إليه الإنسانية قط .. هذا صحيح .. ولكن هذا الخط العريض الذى خطه الإسلام ، فى كرامة الإنسان"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0088.png"}, {"n": 89, "paras": ["وحريته وحقوقه تجاه حكامه وأمرائه ، قد ترك في حياة البشرية آثارا لا شك فيها . وبعض هذه الآثار هو الذي يدفع بالبشرية اليوم إلى إعلان « حقوق الإنسان » ..", "وحقيقة أن هذا الإعلان لم يأخذ طريقه الواقعي في حياة البشرية . وحقيقة أن « الإنسان » ما يزال يلقى المهانة والإذلال والتعذيب والحرمان في شتى أنحاء الأرض . وحقيقة أن بعض المذاهب تجعل مقام الإنسان دون مقام الآلة ، وتقتل حرية الإنسان وكرامته وخصائصه العليا في سبيل وفرة الإنتاج ومضاعفة الدخل ، والتفوق في الأسواق !", "كل هذا صحيح . ولكن هذا الخط ما يزال قائما في مدارك البشرية وتصوراتها . ولم يعد غريبا عليها كما كان يوم جاءها الإسلام . وهي اليوم أقدر على إدراكه وتصوره ، حينما تخاطب به في الجولة القادمة بإذن الله .", "أمة واحدة :", "وجاء الإسلام فوجد الناس يتجمعون على آصرة النسب ، أو يتجمعون على آصرة الجنس ، أو يتجمعون على آصرة الأرض ، أو يتجمعون على آصرة المصالح والمنافع القريبة .. وكلها عصبيات لا علاقة لها بجوهر الإنسان ؛ إنما هي أعراض طارئة على جوهر الإنسان الكريم .", "وقال الإسلام كلمته الحاسمة في هذا الأمر الخطير ، الذي يحدد علاقات الناس بعضهم ببعض تحديدا أخيرا .", "قال : إنه لا لون ولا جنس ، ولا نسب ولا أرض ، ولا مصالح"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0089.png"}, {"n": 90, "paras": ["ولا منافع ، هي التي تجمع بين الناس أو تفرق .. إنما هي العقيدة .. هي علاقتهم بربهم التي تحدد علاقتهم بعضهم ببعض . فعلاقتهم بالله هي التي منحتهم إنسانيتهم. ومن ثم فهى التى تقرر مصائرهم في الدنيا والآخرة سواء . إن النفخة التي جاءتهم من روح الله هى التى جعلت من الإنسان إنسانا ؛ وهى التى كرمت هذا الإنسان وسخرت له ما في السماوات وما في الأرض . فعلى أساس هذه الحقيقة يتجمع الناس أو يفترقون إذن ؛ لا على أساس أي عرض آخر طارىء على حقيقة الإنسان .", "إن آصرة التجمع هي العقيدة ، لأن العقيدة هي أكرم خصائص الروح الإنساني . فأما إذا انبتت هذه الوشيجة فلا آصرة ، ولا تجمع ، ولا كيان !", "إن الإنسانية يجب أن تتجمع على أكرم خصائصها ، لا على مثل ما تتجمع عليه البهائم من الكلأ والمرعى ، أو من الحد والسياج !", "إن هناك حزبين اثنين في الأرض كلها : حزب الله وحزب الشيطان . حزب الله الذي يقف تحت راية الله ويحمل شارته . وحزب الشيطان وهو يضم كل ملة وكل فريق وكل شعب وكل جنس وكل فرد لا يقف تحت راية الله .", "والأمة هي المجموعة من الناس تربط بينها آصرة العقيدة . وهي جنسيتها . وإلا فلا أمة ، لأنه ليست هناك آصرة تجمعها .. والأرض ، والجنس"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0090.png"}, {"n": 91, "paras": ["الآصرة فكرة تعمر القلب والعقل ، وتصور يفسر الوجود والحياة .. ويرتبط بالله ، الذى من نفخة روحه صار الإنسان إنسانا ، وافترق عن البهائم والوحوش ، وافترق تجمعه عن تجمعها ، وامتاز بالتكريم من الله .", "وقال الله للمؤمنين به فى كل أرض ، وفى كل جيل ، ومن كل جنس ولون ، ومن كل فريق وقبيل ، على مدار القرون ، من لدن نوح عليه السلام ، إلى محمد عليه الصلاة والسلام وإلى آخر الزمان : «إن هذه أمتكم أمة واحدة ، وأنا ربكم فاعبدون» . (الأنبياء : ٩٢)", "وفاضل بين الناس بعضهم وبعض على أساس العقيدة ؛ مهما تكن روابط النسب بينهم ، ووشائج الجنس والأرض . فقال :", "«لا تجد قوما يؤمنون بالله واليوم الآخر ، يوادون من حاد الله ورسوله ، ولو كانوا آباءهم أو أبناءهم ، أو إخوانهم ، أو عشيرتهم . أولئك كتب فى قلوبهم الإيمان ، وأيدهم بروح منه ، ويدخلهم جنات تجرى من تحتها الأنهار خالدين فيها ، رضى الله عنهم ورضوا عنه . أولئك حزب الله . ألا إن حزب الله هم المفلحون» . (المجادلة : ٢٢)", "وجعل هنالك سببا واحدا للقتال حيثما لا يكون بد من القتال هو الجهاد فى سبيل الله . وحدد هدف المؤمنين وهدف غير المؤمنين تحديدا حاسما صريحا :"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0091.png"}, {"n": 92, "paras": ["«الذين آمنوا يقاتلون في سبيل الله والذين كفروا يقاتلون في سبيل الطاغوت . فقاتلوا أولياء الشيطان . إن كيد الشيطان كان ضعيفا» . (النساء : ٧٦)", "وكان غريبا على البشرية كلها في ذلك الزمان ، أن يتجمع الناس على عقيدة ، وألا يتجمعوا على أرض ، ولا على جنس ، ولا على لون ، ولا على تجارة ، ولا على أي عرض من الأعراض الزهيدة !", "كانت هذه «المذهبية» بتعبير العصر الحاضر ، مسألة غريبة جدا يوم جاء بها الإسلام .. ولكن هاهى ذى البشرية في الأيام الحاضرة تستسيغها ، فتتجمع أوطان وأقوام ولغات وألوان وأجناس شتى .. على .. على مذهب !", "حقيقة إنها لا تتجمع على عقيدة في الله ، إنما تتجمع على مذهب في الاقتصاد أو الاجتماع .. ذلك أن البشرية هابطة . الأعراض القريبة أكرم عليها من الحقيقة الكبيرة . ولكنها على أية حال تدرك أن رابطة التجمع يمكن أن تكون عقيدة . يمكن أن تكون فكرة . يمكن أن تكون رابطة معنوية !", "وهذا تقدم على كل حال !", "وبقى أن ترتفع البشرية ، وأن تتطلع إلى ما هو أكرم وأعلى . وأن تدرج في المرتقى الصاعد إلى القمة السامقة . على حداء الإسلام في الجولة القادمة . مزودة برصيد الفطرة القديم ؛ ومستعينة كذلك بهذا الرصيد الجديد !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0092.png"}, {"n": 93, "paras": ["ذمة وخلق : ... ولكن الإسلام حين جمع الناس على آصرة العقيدة ، وجعلها هي قاعدة التجمع أو قاعدة التفرقة لم يجعل الإكراه على العقيدة قاعدة الحركة فيه ، ولا قاعدة التعامل . ولم يجعل شريعة الغاب والناب هي التي تحكم علاقاته بالآخرين ، الذين لا يعتنقون عقيدته ، ولا يتجمعون على آصرته .", "لقد فرض الله الجهاد على المؤمنين ؛ لا ليكرهوا الناس على اعتناق الإسلام ؛ ولكن ليقيموا في الأرض نظامه الشامخ العادل القويم . على أن يختار الناس عقيدتهم التي يحبون ، في ظل هذا النظام الذي يشمل المسلم وغير المسلم ، في عدل تام .", "« لا إكراه في الدين قد تبين الرشد من الغي ، فمن يكفر بالطاغوت ويؤمن بالله فقد استمسك بالعروة الوثقى لا انفصام لها ، والله سميع عليم » ( البقرة : ٢٥٦ )", "واعتبر الأرض التي يسيطر عليها النظام الإسلامي وتحكمها الشريعة الإسلامية هي « دار الإسلام » سواء كان سكانها من معتنقي عقيدته كلهم أو كان بعضهم من معتنقي الديانات الأخرى .. واعتبر الأرض التي لا يسيطر عليها النظام الإسلامي ولا تحكمها الشريعة الإسلامية هي « دار الحرب » أيا كان سكانها !", "لم يترك الأمر لشريعة الغاب والناب في العلاقات بين دار الحرب ودار الإسلام . بل نظم هذه العلاقات تنظيما دقيقا ، يحكمه الخلق والنظافة والاستقامة ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0093.png"}, {"n": 94, "paras": ["فدار الإسلام إما أن تكون على عهد وميثاق مع دار الحرب ، فهو العهد المرعى والميثاق المحفوظ ؛ لا غدر فيه ولا خيانة ؛ ولا مباغتة ولا مفاجأة . إلا أن ينقضى الأجل ، أو ينقض العهد أهل دار الحرب .", "وإما أن تكون هناك موادعة – بلا معاهدة مؤقتة – فهى الموادعة إلا أن ينبذ إلى أهل دار الحرب – عند خوف الخيانة – ويعلنوا بانقضاء فترة الموادعة .", "وإما أن تكون هى الحرب .. وللحرب قيود وضمانات . فإن جنحوا للسلم مؤثرين المعاهدة والجزية والرضى بالنظام الإسلامى ، مع حريتهم فى اختيار العقيدة ، . فلهم ذلك على المسلمين :", "«إن شر الدواب عند الله الذين كفروا فهم لا يؤمنون : الذين عاهدت منهم ثم ينقضون عهدهم فى كل مرة ، وهم لا يتقون . فإما تثقفنهم فى الحرب فشرد بهم من خلفهم لعلهم يذكّرون . وإما تخافن من قوم خيانة فانبذ إليهم على سواء . إن الله لا يحب الخائنين . ولا يحسبن الذين كفروا سبقوا إنهم لا يعجزون . وأعدوا لهم ما استطعتم من قوة ومن رباط الخيل ، ترهبون به عدو الله وعدوكم ، وآخرين من دونهم لا تعلمونهم الله يعلمهم . وما تنفقوا من شئ فى سبيل الله يوف إليكم وأنتم لا تظلمون . وإن جنحوا للسلم فاجنح لها ، وتوكل على الله ، إنه هو السميع العليم »", "( الأنفال : ٥٥ – ٦١ )", "وأكد على الوفاء بالعهد ، مبطلا حجة « مصلحة الدولة » فإنها لا تجيز نقض العهود :"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0094.png"}, {"n": 95, "paras": ["« وأوفوا بعهد الله إذا عاهدتم ، ولا تنقضوا الأيمان بعد توكيدها وقد جعلتم الله عليكم كفيلا ، إن الله يعلم ما تفعلون . ولا تكونوا كالتي نقضت غزلها من بعد قوة أنكاثا ، تتخذون أيمانكم دخلا بينكم ، أن تكون أمة هى أربى من أمة . إنما يبلوكم الله به ، وليبين لكم يوم القيامة ما كنتم فيه تختلفون » ...", "( النحل : ٩١ - ٩٢ )", "فإذا كانت الحرب فهى الحرب التى لا تهتك فيها حرمة ؛ ولا يقتل فيها صبى ولا شيخ ولا امرأة ؛ ولا يحرق فيها زرع ، ولا يتلف فيها ضرع ؛ ولا يمثل فيها بإنسان ؛ ولا تصيب إلا المقاتلين الذين يحملون السلاح فى وجه المسلمين .. وهذه وصية أبى بكر لجيش أسامة وهو ذاهب لمقاتلة الروم :", "« لا تخونوا ، ولا تغلوا ، ولا تغدروا ، ولا تمثلوا ، ولا تقتلوا طفلا، صغيرا ولا شيخا كبيرا ، ولا امرأة . ولا تعقروا نخلا ولا تحرقوه ، ولا تقطعوا شجرة مثمرة . ولا تذبحوا شاة ولا بعيرا إلا لمأكلة . وسوف تمرون بأقوام قد فرغوا أنفسهم فى الصوامع ، فدعوهم وما فرغوا أنفسهم له ... اندفعوا باسم الله » ...", "ولست أنوى هنا إستقصاء قوانين المعاملات بين دار الإسلام ودار الحرب ، ولا بين المسلمين وسائر الأقوام . فهذا البحث المجمل ليس مكان هذا التفصيل .. إنما أريد أن أصل إلى الخط العريض الذى أقامه الإسلام فى الأرض ، للتعامل بين المعسكرات المختلفة ، حيث لم يكن لذلك الخط وجود . فما كانت الأمم يوم جاء تتعامل إلا بقانون"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0095.png"}, {"n": 96, "paras": ["السيف وحده ، أو قانون الغاب والناب فمن كان يملك القوة فكل شيء له حلال . والمغلوب لا حقوق له على الإطلاق !", "هذا الخط الإسلامى العريض لم يذهب ولم يمح من واقع البشرية فقد بدأ العالم فى القرن السابع عشر الميلادى (القرن الحادى عشر الهجرى) فى التعامل على أساس من القانون ! وأخذ يخطو خطوات متوالية فى «القانون الدولى» وجعل يحاول إقامة هيئات دولية للتحكيم فى القرن التاسع عشر ، وظلت هذه التشكيلات تتأرجح بين النجاح والفشل حتى اللحظة الحاضرة .. ووجدت بحوث قوية وضخمة فى القوانين الدولية .", "ومن ثم لم تعد الأنظمة التى جاء بها الإسلام غريبة غربتها يوم جاء .", "حقيقة أن البشرية لم ترتفع قط إلى المستوى الأخلاقى الذى بلغته الجماعة المسلمة فى التعامل الواقعى .", "وحقيقة أن نكسات قوية قد وقعت فى هذا العصر حتى فى القوانين الدولية النظرية التى وصل إليها الفقه القانونى فى العالم الغربى . فألغى شرط إعلان الحرب . ونقض المعاهدات ، وإنهاء الموادعات ! وأصبح الأمر غيلة أشد من حالة الوحوش فى الغاب !", "وحقيقة إن دوافع الحرب والسلم لم ترتفع قط عن المصالح والمغانم والأسلاب والأسواق ؛ ولم ترق قط إلى أفق الفكر والعقيدة والخير والعدل والصلاح التى يستهدفها الجهاد فى الإسلام .", "كل هذا صحيح . ولكن خط التعامل الدولى على أساس من القانون"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0096.png"}, {"n": 97, "paras": ["المعروف لجميع الأطراف.. قد وجد. أوجده الإسلام لأول مرة. وخطه في حياة البشرية ذلك المنهج الإلهي القويم الرفيع.", "فإذا خوطبت البشرية مرة أخرى بهذا المنهج لم يكن هذا الخط غريبا عليها ولا مستنكرا.. قد تظل أسسه الأخلاقية الرفيعة غريبة على البشرية الواغلة في مستنقع الجاهلية ، فترة من الزمان. ولكن أصل الخط وصورته لن تكون غريبة ولا مستنكرة.", "والإسلام الذى اعتمد أول مرة على رصيد الفطرة وحده فى إقرار مبادئه ، ورسم خطوطه ، سيعتمد فى الجولة القادمة على ذلك الرصيد. ويعتمد إلى جانبه على تلك التجارب الواقعة المعهودة. وسيكون بإذن الله أقدر على استئناف خطواته من جديد.. بهذا الرصيد."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0097.png"}, {"n": 98, "paras": ["وَبَعْد !", "وبعد ، فإننا لا نملك فى هذا البحث المجمل أن نمضى أكثر من هذا فى الحديث عن الخطوط العريضة التى خطها الإسلام فى حياة البشرية وتاريخها وواقعها ، والتى لم تكن معروفة من قبل ولا مألوفة ، والتى بقيت منها ملامح وآثار فى حياة البشر ، مهما تكن باهتة . ومهما تكن منحرفة ، ومهما تكن هابطة عن القمة السامقة التى ارتفع إليها الناس فى ظل المنهج الإلهى القويم ..", "فهذه النماذج القليلة التى أشرنا إليها تصلح إشارة إلى عشرات الخطوط العريضة التى أقرها ذلك المنهج . بعد أن أنشأها إنشاء . ويمكن القياس عليها فى شتى جوانب الحياة البشرية خلال أربعمائة وألف عام .", "ولكن الكلمة التى لابد أن تقال فى ختام هذا البحث المجمل ، كى لا يغتر الدعاة إلى الله ، وإلى منهج الله ، بهذه العوامل المساعدة ، وينسوا أخذ الأهبة كاملة لأشواك الطريق وعوائقه ..", "هذه الكلمة ينبغى أن تكون عن الخطوط المضادة ، وعن عوائق الطريق الكأداء !"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0098.png"}, {"n": 99, "paras": ["إن البشرية يحملتها اليوم .. أبعد من الله .. إن الركام الذى يرين على الفطرة أثقل وأظلم . فالجاهليات القديمة كانت جاهليات جهل وسذاجة وفتوة . أما الجاهلية الحاضرة فجاهلية علم ! وتعقيد ! واستهتار !", "إن الفتنة بفتوحات العلم في القرنين الثامن عشر والتاسع عشر الميلاديين كانت فتنة طاغية . والهروب من الكنيسة ومن إله الكنيسة الذي تصول باسمه وتجول ، وتحرق العلماء ، وتعذب المفكرين ، وتناهض النهضات .. كان هروبا مجنونا آبقا لا يلوى على شيء ، ولا يبقى على مقدس !", "حقيقة إن العلم ذاته منذ مطلع هذا القرن قد أخذ يقود كبار العلماء إلى الله من جديد . والفطرة التى أشقاهما الضرب في التيه قد بدأ يبدو عليها التعب والحنين إلى الله من جديد .. ولكن تلك الفتنة ما تزال في عنفوانها . وقد ينقضى هذا القرن كله قبل أن تظهر البوادر الكاملة لعودة القطيع الشارد من التيه البعيد .", "والحياة الدنيا قد اتسعت رقعتها في حس الناس وواقعهم ! اتسعت رقعتها بما استحدثته الحضارة من وسائل الحياة والمتاع والاستقرار في الأرض ، وأحس الناس بضخامة هذه الحياة في واقعهم وفي مشاعرهم سواء . وأضافت العلوم والثقافات والفنون والهوايات مساحات ضخمة إلى رقعة الحياة فى واقع الناس وفى مشاعرهم سواء ! ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0099.png"}, {"n": 100, "paras": ["ولو قام هذا كله على أساس من المعرفة بالله ، وبخصائص الألوهية وخصائص العبودية ، وعلى أساس من الحقيقة العميقة : حقيقة أن الله هو الذي استخلف الإنسان في الأرض ، وسخر له ما فيها ، وزوده بالمواهب والاستعدادات التى تعينه على الخلافة ، وتيسر له طيبات الحياة كلها .. وأنه مبتلى فى هذا كله ليحاسب فى الآخرة على ما قدم في حياته الدنيا ..", "لو قام هذا كله على هذا الأساس الصحيح ، لكانت هذه المساحات الجديدة التى أضافها العلم وأضافتها الحضارة ، لرقعة الحياة في واقع الناس ومشاعرهم .. مساحات تضاف إلى رقعة الإيمان ، وتزيد الناس قربا من الله ومنهجه القويم الممثل في الإسلام .", "ولكن هذا كله إنما قام على أساس الهروب من الكنيسة الطاغية ومن إلهها الذى تستطيل به على الناس ! فكانت هذه الإضافة إلى رقعة الحياة مبعدة عن الله ، وعقبة فى الطريق إليه ، ينبغى أن يحسب حسابها الدعاة !", "حقيقة أن البشرية قد شقيت وتعبت من حمل هذه الحضارة المادية ، والمضى فى متاعها المترف . وحقيقة أن الفساد والانحلال والأمراض العصبية والنفسية ، والشذوذ العقلى والجنسى ، وآثار ذلك كله تنخر فى جسم هذه الحضارة ، وتشق الأمم والأفراد ، وتفتح الأعين بعنف على الشر والفساد والدمار ..", "ولكن البشرية ما تزال فى هياجها الحيوانى ، وفى خمارها الجنونى ، وفى نشوتها المعربدة .. وقد ينقضى هذا القرن كله قبل أن تتفتح العيون"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0100.png"}, {"n": 101, "paras": ["فعلا وتصحو الأدمغة من هذا الخمار ، وتكف البشرية أو تفكر في أن نكف عن هذا الدوار !", "وكانت الجاهليات الأولى قريبة العهد بالبداوة ، فيها-فتوة البداوة وجدها على كل حال . كانت للناس تقاليد ، وكانت أخلاق الفتوة في الغالب تحكم تصرفات الناس . وعلى قدر ما كانت هذه الفتوة تجعل المعركة بين أصحاب الدعوة وأصحاب الجاهلية قاسية وعنيفة ، فإنها كانت تجعلها مكشوفة وصريحة .. كانت الفطرة قريبة .. تلبى وتجيب ، من قريب ، من وراء العناد والكبرياء .. وكان هناك الجد الصارم فى الكفر أو الإيمان سواء .. وهذا على كل ما يثيره من المتاعب ، خير من الميوعة والاستهتار وعدم المبالاة ! والبشرية اليوم تعانى من التميع والاستهتار والاستخفاف بكل عقيدة وكل رأى وكل مذهب . كما تعانى من نفاق القلب ، وكيد الضعف وخبث الاحتيال ! وكلها عقبات فى طريق الدعوة إلى الله ، ومعوقات عن الاستقامة على منهج الله ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0101.png"}, {"n": 102, "paras": ["وغير هذا كثير من لونه ، ومن ألوان شتى ، ينبغى ألا نهون من شأنه ، كي لا يغتر الدعاة إلى الله بالعوامل المساعدة ، ثم لا يتزودوا كل الزاد ..", "ولكن ما الزاد ؟", "إنه زاد واحد .. زاد التقوى .. إنه الشعور بالله على حقيقته .. إنه التعامل مباشرة مع الله .. والثقة المطلقة بوعده الجازم الحاسم : « وكان حقا علينا نصر المؤمنين » ( الروم : ٤٧ )", "والأمر كله هو أمر العصبة المؤمنة التى تضع يدها في يد الله . ثم تمضى في الطريق . وعدُ الله لها هو واقعها الذى لا واقع غيره ، ومرضاة الله هى هدفها الأول وهدفها الأخير .", "وهذه العصبة التى تجرى بها سنة الله فى تحقيق منهج الله ، وهى التى تنفض ركام الجاهلية عن الفطرة ، وهى التى يتمثل فيها قدر الله فى أن تعلو كلمته في الأرض ، ويتسلم منهجه الزمام :", "« قد خلت من قبلكم سنن ، فسيروا فى الأرض فانظروا كيف كان عاقبة المكذبين . هذا بيان للناس وهدى وموعظة للمتقين . ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين . إن يمسسكم قرح فقد مس القوم قرح مثله ، وتلك الأيام نداولها بين الناس ، وليعلم الله الذين آمنوا ويتخذ منكم شهداء ، والله لا يحب الظالمين . وليمحص الله الذين آمنوا ويمحق الكافرين » . ( آل عمران : ١٣٧ - ١٤١ )", "وصدق الله العظيم ."], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0102.png"}, {"n": 103, "paras": ["يصدر عن دار الشروق في شرعية قانونية كاملة", "مكتبة الأستاذ سيد قطب", "* في ظلال القرآن", "* مشاهد القيامة في القرآن", "* التصوير الفني في القرآن", "* الإسلام ومشكلات الحضارة", "* خصائص التصور الإسلامي ومقوماته", "* النقد الأدبي أصوله ومناهجه", "* مهمة الشاعر في الحياة", "* هذا الدين", "* السلام العالمي والإسلام", "* معالم في الطريق", "* دراسات إسلامية", "* نحو مجتمع إسلامي", "* في التاريخ فكرة ومنهاج", "* تفسير آيات الربا", "* تفسير سورة الشورى", "* كتب وشخصيات", "* المستقبل لهذا الدين", "* معركتنا مع اليهود", "* معركة الإسلام والرأسمالية", "* العدالة الاجتماعية في الإسلام", "مكتبة الأستاذ محمد قطب", "* الإنسان بين المادية والإسلام", "* منهج الفن الإسلامي", "* منهج التربية الإسلامية (الجزء الأول)", "* منهج التربية الإسلامية (الجزء الثاني)", "* معركة التقاليد", "* في النفس والمجتمع", "* التطور والثبات في حياة البشرية", "* دراسات في النفس الإنسانية", "* هل نحن مسلمون", "* قبسات من الرسول", "* شبهات حول الإسلام", "* جاهلية القرن العشرين", "* دراسات قرآنية", "* مفاهيم ينبغي أن تصحح", "* مذاهب فكرية معاصرة", "* كيف نكتب التاريخ الإسلامي", "تحت الطبع", "* المستشرقون والإسلام"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0103.png"}, {"n": 104, "paras": ["من كتب دار الشروق الإسلامية", "مصحف الشروق المفسر الميسر مختصر تفسير الإمام الطبري تحفة المصاحف وقمة التفاسير في أحجام مختلفة وطبعات منفصلة لبعض الأجزاء", "تفسير القرآن الكريم الإمام الأكبر محمود شلتوت", "الإسلام عقيدة وشريعة الإمام الأكبر محمود شلتوت", "الفتاوى الإمام الأكبر محمود شلتوت", "من توجيهات الإسلام الإمام الأكبر محمود شلتوت", "إلى القرآن الكريم الإمام الأكبر محمود شلتوت", "الوصايا العشر الإمام الأكبر محمود شلتوت", "المسلم في عالم الاقتصاد الأستاذ مالك بن نبي", "أنبياء الله الأستاذ أحمد بهجت", "نبي الإنسانية الأستاذ أحمد حسين", "ربانية لا رهبانية أبو الحسن علي الحسني الندوي", "الحجة في القراءات السبع", "- رتقديم الدكتور عبد العال سالم مكرم", "الفكر الإسلامي بين العقل والوحي الدكتور عبد العال سالم مكرم", "على مشارف القرن الخامس عشر الهجري الأستاذ ابراهيم بن علي الوزير", "الرسالة الخالدة الأستاذ عبد الرحمن عزام", "محمد رسولاً نبياً الأستاذ عبد الرزاق نوفل", "مسلمون بلا مشاكل الأستاذ عبد الرزاق نوفل", "الإسلام في مفترق الطرق الدكتور أحمد عروة", "العقوبة في الفقه الإسلامي الدكتور أحمد فتحي بهنسي", "موقف الشريعة من نظرية الدفاع الاجتماعي الدكتور أحمد فتحي بهنسي", "الجرائم في الفقه الإسلامي الدكتور أحمد فتحي بهنسي", "مدخل الفقه الجنائي الإسلامي الدكتور أحمد فتحي به"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0104.png"}, {"n": 105, "paras": ["القضاء والقدر فضيلة الشيخ متولي الشعراوي قضايا إسلامية فضيلة الشيخ متولي الشعراوي التعبير الفني في القرآن الدكتور بكري الشيخ أمين أدب الحديث النبوي الدكتور بكري الشيخ أمين الإسلام في مواجهة الماديين والملحدين الأستاذ عبد الكريم الخطيب اليهود في القرآن الأستاذ عبد الكريم الخطيب أيام الله الأستاذ عبد الكريم الخطيب مسلمون وكفى الأستاذ عبد الكريم الخطيب الدعوة الوهابية الأستاذ عبد الكريم الخطيب قال الأولون أدب ودين الأستاذ السيد أبو ضيف المدني قل يا رب الأستاذ السيد أبو ضيف المدني الإيمان الحق المستشار علي جريشة الجديد حول أسماء الله الحسنى الأستاذ عبد المغني سعيد الجائز والممنوع في الصيام الدكتور عبد العظيم المطاعني مناسك الحج والعمرة في ضوء المذاهب الأربعة الدكتور عبد العظيم المطاعني أيها الولد المحب الإمام الغزالي الأدب في الدين الإمام الغزالي شرح الوصايا العشر للإمام حسن البنا القرآن والسلطان الأستاذ فهمي هويدي خفايا الإسراء والمعراج الأستاذ مصطفى الكيك الخطابة وإعداد الخطيب الدكتور عبد الجليل شلبي تاريخ القرآن الأستاذ إبراهيم الأبياري الإسلام والمبادئ المستوردة الدكتور عبد المنعم النمر سلسلة أعلام الإسلام ١٦/١ سلسلة أهل البيت ٦/١ إسهام علماء المسلمين في الرياضيات تأليف الدكتور علي عبد الله الدقاع تعريب وتعليق الدكتور جلال شوقي مراجعة الدكتور عبد العزيز السيد الخبر الواحد في السنة والتراث وأثره في الفقه الإسلامي الدكتورة سهير وشاد مهنا الأديان القديمة في الشرق دكتور رؤوف شلبي"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0105.png"}, {"n": 106, "paras": ["رقم الإيداع . ١٧٨٩ / ١٩٨٩ ترقيم الدولي . ١ - ٢٩٧ - ١٤٨ - ٩٧٧", "مطابع الشروق القاهرة : ٨ شارع سيبويه المصرى - ت: ٤٠٢٣٣٩٩ - فاكس: ٤٠٣٧٥٦٧ (٠٢) بيروت : ص . ب : ٨٠٦٤ - هاتف : ٣١٥٨٥٩ - ٨١٧٢١٣ - فاكس : ٨١٧٧٦٥ (٠١)"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0106.png"}, {"n": 107, "paras": ["فهرست المحتويات", "مقدمة ٥ المدخل ٩ الفصل الأول: مفهوم التنمية البشرية ١٣ الفصل الثاني: التنمية البشرية في الإسلام ٢٥ الفصل الثالث: مقومات التنمية البشرية ٤١ الفصل الرابع: معوقات التنمية البشرية ٥٧ الفصل الخامس: آليات تفعيل التنمية البشرية ٧٣ الخاتمة ٨٩ المصادر والمراجع ٩٣"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0107.png"}, {"n": 108, "paras": ["مكتبة سيد قطب في ظلال القرآن العدالة الاجتماعية في الإسلام خصائص التصور الإسلامي ومقوماته النقد الأدبي أصوله ومناهجه كتب وشخصيات الإسلام ومشكلات الحضارة التصوير الفني في القرآن مشاهد القيامة في القرآن معركتنا مع اليهود تفسير سورة الشورى تفسير آيات الربا دراسات إسلامية السلام العالمي والإسلام معركة الإسلام والرأسمالية في التاريخ فكرة ومنهاج معالم في الطريق هذا الدين المستقبل لهذا الدين نحو مجتمع إسلامي"], "img": "../../../_ocr-work/libocr/hadha-al-din/pages/0108.png"}], "translations": [{"href": "../hadha-al-din-ms/", "label": "Bahasa Melayu"}]};
